insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-13', 'listening', null, null, '/audio/listening/q-listening-13.mp3', 'Woman: Good afternoon, welcome to the Marina Hotel. Do you have a reservation?
Man: Yes, under the name Faisal Al-Harbi, for two nights starting today.
Woman: I see a reservation here, but it''s actually for a single room, not the double room you mentioned.
Man: That''s strange, I definitely booked a double room online.
Woman: I apologize for the mix-up. Let me check — yes, we do have a double room available, and I''ll upgrade you at no extra charge for the inconvenience.', 'What problem does the man encounter at the hotel?', '[{"id":"a","text":"His reservation was cancelled"},{"id":"b","text":"The hotel has no rooms available at all"},{"id":"c","text":"He forgot his reservation name"},{"id":"d","text":"His room booking doesn''t match what he ordered"}]'::jsonb, 'd', 'The woman finds "a single room, not the double room" he mentioned.', 'medium', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
