insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-16', 'listening', null, null, '/audio/listening/q-listening-16.mp3', 'Student: Professor Al-Zahrani, could I have a few extra days for the research paper? My laptop crashed and I lost some of my notes.
Professor: I''m sorry to hear that. When do you think you can submit it?
Student: I could have it ready by next Wednesday instead of this Friday.
Professor: That should be fine, as long as you email me to confirm the new deadline in writing.', 'Why does the student request an extension?', '[{"id":"a","text":"She was sick for most of the week before the deadline"},{"id":"b","text":"She forgot about the assignment entirely until today"},{"id":"c","text":"Her laptop crashed and she lost some notes"},{"id":"d","text":"The professor changed the topic at the last minute"}]'::jsonb, 'c', 'She says, "My laptop crashed and I lost some of my notes."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
