insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-30', 'listening', null, null, '/audio/listening/q-listening-30.mp3', 'Woman: I''d like to return this blender. It stopped working after two weeks.
