insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-33', 'listening', null, null, '/audio/listening/q-listening-33.mp3', 'Agent: Your flight to Cairo has been delayed by two hours because of bad weather.
