insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-45', 'listening', null, null, '/audio/listening/q-listening-45.mp3', 'Man: I''m calling about the apartment listed online — is it still available?
