insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-57', 'listening', null, null, '/audio/listening/q-listening-57.mp3', 'Man: The forecast says heavy rain all afternoon, so the picnic is cancelled.
Woman: Oh no, the kids were really looking forward to it.
Man: The museum is open late tonight and has a special children''s science show at four.
Woman: That sounds perfect. Should I book tickets now?
Man: Yes, and I''ll check if the parking is still free after six.
Woman: Great, let''s meet at the museum entrance at three thirty.', 'Why was the picnic cancelled?', '[{"id":"a","text":"The park is closed for maintenance this weekend."},{"id":"b","text":"The children got sick and cannot go outside."},{"id":"c","text":"Heavy rain is forecast for the afternoon."},{"id":"d","text":"The tickets for the park were sold out."}]'::jsonb, 'c', 'The man says "the forecast says heavy rain all afternoon, so the picnic is cancelled."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-58', 'listening', null, null, '/audio/listening/q-listening-57.mp3', 'Man: The forecast says heavy rain all afternoon, so the picnic is cancelled.
Woman: Oh no, the kids were really looking forward to it.
Man: The museum is open late tonight and has a special children''s science show at four.
Woman: That sounds perfect. Should I book tickets now?
Man: Yes, and I''ll check if the parking is still free after six.
Woman: Great, let''s meet at the museum entrance at three thirty.', 'What does the man suggest as an alternative plan?', '[{"id":"a","text":"Watching a movie at home together as a family"},{"id":"b","text":"Moving the picnic to Sunday if the weather improves"},{"id":"c","text":"Visiting the aquarium in the city instead"},{"id":"d","text":"Going to the museum''s children''s science show"}]'::jsonb, 'd', 'He mentions "a special children''s science show at four" at the museum, which the woman agrees to.', 'medium', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-59', 'listening', null, null, '/audio/listening/q-listening-57.mp3', 'Man: The forecast says heavy rain all afternoon, so the picnic is cancelled.
Woman: Oh no, the kids were really looking forward to it.
Man: The museum is open late tonight and has a special children''s science show at four.
Woman: That sounds perfect. Should I book tickets now?
Man: Yes, and I''ll check if the parking is still free after six.
Woman: Great, let''s meet at the museum entrance at three thirty.', 'Where and when do they agree to meet?', '[{"id":"a","text":"At the museum entrance at three thirty"},{"id":"b","text":"At the park gate at four o''clock"},{"id":"c","text":"At the parking lot at six o''clock"},{"id":"d","text":"At the science center at noon"}]'::jsonb, 'a', 'The woman says, "let''s meet at the museum entrance at three thirty," and the man agrees.', 'medium', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-60', 'listening', null, null, '/audio/listening/q-listening-60.mp3', 'Woman: I ordered a laptop stand three days ago and it was supposed to arrive yesterday, but nothing came.
Man: I''m sorry about that. Let me check the tracking... It shows the package was delayed at the sorting center.
Woman: Can you send it today?
Man: The earliest delivery slot is tomorrow between nine and noon. I''ll mark it as urgent so it''s the first drop.
Woman: Okay, and please send me a confirmation message when it''s out for delivery.', 'Why hasn''t the woman received her order?', '[{"id":"a","text":"The item is out of stock at the nearest warehouse."},{"id":"b","text":"The package was delayed at the sorting center."},{"id":"c","text":"The delivery address on the order was wrong."},{"id":"d","text":"She never placed the order in the first place."}]'::jsonb, 'b', 'The man checks the tracking and reports "the package was delayed at the sorting center."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-61', 'listening', null, null, '/audio/listening/q-listening-60.mp3', 'Woman: I ordered a laptop stand three days ago and it was supposed to arrive yesterday, but nothing came.
Man: I''m sorry about that. Let me check the tracking... It shows the package was delayed at the sorting center.
Woman: Can you send it today?
Man: The earliest delivery slot is tomorrow between nine and noon. I''ll mark it as urgent so it''s the first drop.
Woman: Okay, and please send me a confirmation message when it''s out for delivery.', 'What does the man offer to do about the delivery?', '[{"id":"a","text":"Cancel the order and refund the payment to her card"},{"id":"b","text":"Deliver it personally to her home today"},{"id":"c","text":"Ship a replacement from another warehouse overnight"},{"id":"d","text":"Mark it as urgent so it is the first delivery tomorrow"}]'::jsonb, 'd', 'He says "I''ll mark it as urgent so it''s the first drop" for tomorrow''s delivery slot.', 'medium', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-62', 'listening', null, null, '/audio/listening/q-listening-60.mp3', 'Woman: I ordered a laptop stand three days ago and it was supposed to arrive yesterday, but nothing came.
Man: I''m sorry about that. Let me check the tracking... It shows the package was delayed at the sorting center.
Woman: Can you send it today?
Man: The earliest delivery slot is tomorrow between nine and noon. I''ll mark it as urgent so it''s the first drop.
Woman: Okay, and please send me a confirmation message when it''s out for delivery.', 'What does the woman ask to receive before the delivery?', '[{"id":"a","text":"A confirmation message when the package is out for delivery"},{"id":"b","text":"A refund receipt sent to her email address"},{"id":"c","text":"The tracking number by post to her home address"},{"id":"d","text":"A phone call from the driver before he arrives"}]'::jsonb, 'a', 'She asks, "please send me a confirmation message when it''s out for delivery."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-1', 'writingAnalysis', null, null, null, null, 'Identify the error: "Each of the employees are required to submit their timesheet by Friday."', '[{"id":"a","text":"\"are\" should be \"is\""},{"id":"b","text":"\"Each of\" should be \"All of\""},{"id":"c","text":"\"their\" should be \"his\""},{"id":"d","text":"\"submit\" should be \"submitting\""}]'::jsonb, 'a', '"Each of the employees" is singular, so the verb should be "is", not "are".', 'medium', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-2', 'writingAnalysis', null, null, null, null, 'Identify the error: "She has less problems than I expected with the new software."', '[{"id":"a","text":"\"has\" should be \"have\""},{"id":"b","text":"\"less\" should be \"fewer\""},{"id":"c","text":"\"expected\" should be \"expecting\""},{"id":"d","text":"No error"}]'::jsonb, 'b', '"Problems" is countable, so "fewer" is correct; "less" is for uncountable nouns.', 'medium', array['error-identification','countable-uncountable']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-3', 'writingAnalysis', null, null, null, null, 'Identify the error: "The manager, along with two supervisors, were present at the safety inspection."', '[{"id":"a","text":"\"along with\" should be \"and\""},{"id":"b","text":"\"present\" should be \"presence\""},{"id":"c","text":"\"were\" should be \"was\""},{"id":"d","text":"\"the\" should be removed"}]'::jsonb, 'c', '"Along with..." doesn''t change the subject''s number; the subject is "the manager" (singular), so "was" is correct.', 'hard', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-4', 'writingAnalysis', null, null, null, null, 'Identify the error: "Having finished the project early, the deadline was no longer a concern for the team."', '[{"id":"a","text":"\"no longer\" should be \"no more\", because \"longer\" cannot follow \"no\""},{"id":"b","text":"\"for the team\" should be removed, because it repeats \"the deadline\""},{"id":"c","text":"No error — the sentence is correct as it is written"},{"id":"d","text":"\"Having finished\" is a dangling modifier — it doesn''t logically refer to \"the deadline\""}]'::jsonb, 'd', 'The introductory phrase should modify "the team" (who finished the project), not "the deadline" — a classic dangling modifier.', 'hard', array['error-identification','dangling-modifiers']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-5', 'writingAnalysis', null, null, null, null, 'Identify the error: "The manager asked us to arriving early, prepare the materials, and to greet guests."', '[{"id":"a","text":"\"prepare\" should be \"preparing\", to match the first verb in the list"},{"id":"b","text":"\"to arriving\" should be \"to arrive\", to match the parallel infinitive structure"},{"id":"c","text":"\"to greet\" should be \"greeting\", to match the first verb in the list"},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'b', 'A list of parallel actions should share the same grammatical form — "to arrive, prepare, and greet" (infinitives without "to" after the first).', 'medium', array['error-identification','parallel-structure']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-6', 'writingAnalysis', null, null, null, null, 'Identify the error: "By next year, she will have working here for two decades."', '[{"id":"a","text":"\"By next year\" should be \"Until next year\", because the action continues"},{"id":"b","text":"\"two decades\" should be \"two decade\", because \"two\" is a number"},{"id":"c","text":"\"will have working\" should be \"will have been working\""},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'c', 'The future perfect continuous requires "will have been" + present participle, not "will have" + present participle.', 'hard', array['error-identification','tenses']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-7', 'writingAnalysis', null, null, null, null, 'Identify the error: "Between you and I, the proposal needs major revisions."', '[{"id":"a","text":"\"Between\" should be \"Among\""},{"id":"b","text":"\"needs\" should be \"need\""},{"id":"c","text":"No error"},{"id":"d","text":"\"I\" should be \"me\""}]'::jsonb, 'd', 'As the object of the preposition "between," the correct pronoun is the object form "me," not the subject form "I."', 'medium', array['error-identification','pronoun-case']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-8', 'writingAnalysis', null, null, null, null, 'Identify the error: "Neither the manager nor the employees was informed about the schedule change."', '[{"id":"a","text":"\"was\" should be \"were\""},{"id":"b","text":"\"Neither\" should be \"Either\""},{"id":"c","text":"\"informed\" should be \"inform\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'With "neither...nor," the verb agrees with the nearer subject — "employees" (plural) — so "were" is correct.', 'hard', array['error-identification','subject-verb-agreement','correlative-conjunctions']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-9', 'writingAnalysis', null, null, null, null, 'Identify the error: "We don''t have no more time to waste on this project."', '[{"id":"a","text":"\"waste\" should be \"wasting\", because it follows the word \"on\""},{"id":"b","text":"\"time\" should be \"times\", because the sentence is about many projects"},{"id":"c","text":"\"don''t have no\" should be \"don''t have any\""},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'c', '"Don''t have no" is a double negative; standard English uses "don''t have any".', 'easy', array['error-identification','double-negative']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-10', 'writingAnalysis', null, null, null, null, 'Identify the error: "The companys'' profits increased significantly last quarter."', '[{"id":"a","text":"\"profits\" should be \"profit\""},{"id":"b","text":"\"increased\" should be \"increasing\""},{"id":"c","text":"No error"},{"id":"d","text":"\"companys''\" should be \"company''s\""}]'::jsonb, 'd', 'A singular possessive noun takes ''s, not s'': "company''s", not "companys''".', 'medium', array['error-identification','possessives']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-11', 'writingAnalysis', null, null, null, null, 'Identify the error: "The proposal was rejected, the board felt it lacked sufficient detail."', '[{"id":"a","text":"The comma should be replaced with \"because\""},{"id":"b","text":"\"rejected\" should be \"rejecting\", because the action is still continuing"},{"id":"c","text":"\"board\" should be \"boards\", because several people are mentioned"},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'a', 'Joining two independent clauses with only a comma creates a comma splice; a conjunction like "because" is needed.', 'hard', array['error-identification','comma-splice']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-12', 'writingAnalysis', null, null, null, null, 'Identify the error: "The new policy will make employees to work fewer hours."', '[{"id":"a","text":"\"will make\" should be \"made\""},{"id":"b","text":"\"to work\" should be \"work\""},{"id":"c","text":"\"fewer\" should be \"less\""},{"id":"d","text":"No error"}]'::jsonb, 'b', '"Make + object" is followed by a bare infinitive, not "to" + verb: "make employees work".', 'medium', array['error-identification','causative']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-13', 'writingAnalysis', null, null, null, null, 'Identify the error: "I am looking forward to hear from you soon."', '[{"id":"a","text":"\"am looking\" should be \"look\", because the verb is in the present"},{"id":"b","text":"\"soon\" should be \"early\", because it describes the time of the reply"},{"id":"c","text":"No error — the sentence is correct as it is written"},{"id":"d","text":"\"to hear\" should be \"to hearing\""}]'::jsonb, 'd', '"Look forward to" takes a gerund ("to hearing"), because "to" here is a preposition, not part of an infinitive.', 'easy', array['error-identification','gerunds-infinitives']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-14', 'writingAnalysis', null, null, null, null, 'Identify the error: "The equipment in the computer labs are outdated."', '[{"id":"a","text":"\"are\" should be \"is\""},{"id":"b","text":"\"equipment\" should be \"equipments\""},{"id":"c","text":"\"outdated\" should be \"out of date\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Equipment" is an uncountable noun that takes a singular verb, so "the equipment...is outdated".', 'medium', array['error-identification','subject-verb-agreement','countable-uncountable']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-15', 'writingAnalysis', null, null, null, null, 'Identify the error: "Hardly had he arrived at the station when the train had left."', '[{"id":"a","text":"\"had he arrived\" should be \"he had arrived\""},{"id":"b","text":"\"had left\" should be \"left\""},{"id":"c","text":"\"when\" should be \"than\""},{"id":"d","text":"No error"}]'::jsonb, 'b', 'In the "hardly...when" structure the second clause takes the simple past ("the train left"), not the past perfect.', 'hard', array['error-identification','inversion','tenses']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-16', 'writingAnalysis', null, null, null, null, 'Identify the error: "The new employees must complete the training before they will start working."', '[{"id":"a","text":"\"must complete\" should be \"must have completed\""},{"id":"b","text":"\"working\" should be \"work\""},{"id":"c","text":"\"will start\" should be \"start\""},{"id":"d","text":"No error"}]'::jsonb, 'c', 'Time clauses introduced by "before", "when", or "after" use the present simple for future meaning: "before they start working".', 'medium', array['error-identification','tenses','time-clauses']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-17', 'writingAnalysis', null, null, null, null, 'Identify the error: "Despite of the warning, many students ignored the announcement."', '[{"id":"a","text":"\"Despite of\" should be \"Despite\""},{"id":"b","text":"\"ignored\" should be \"ignore\""},{"id":"c","text":"\"the warning\" should be \"warnings\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Despite" is used alone (or as "in spite of"), never "despite of".', 'easy', array['error-identification','prepositions']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-18', 'writingAnalysis', null, null, null, null, 'Identify the error: "If he had studied harder, he would pass the exam."', '[{"id":"a","text":"\"had studied\" should be \"studied\", because the result is in the past"},{"id":"b","text":"\"would pass\" should be \"would have passed\""},{"id":"c","text":"\"harder\" should be \"hard\", because it follows the verb directly"},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'b', 'This is a third conditional (past unreal situation): "If + past perfect, would have + past participle" — "would have passed".', 'hard', array['error-identification','conditionals']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-19', 'writingAnalysis', null, null, null, null, 'Identify the error: "The committee has reached its decision, the results will be announced tomorrow."', '[{"id":"a","text":"\"has\" should be \"have\", because \"committee\" is plural here"},{"id":"b","text":"\"its\" should be \"it''s\", because it shows possession"},{"id":"c","text":"A comma splice joins two independent clauses without a conjunction."},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'c', '"The committee has reached its decision" and "the results will be announced" are both independent clauses; joining them with only a comma creates a comma splice.', 'medium', array['error-identification','comma-splice']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-20', 'writingAnalysis', null, null, null, null, 'Identify the error: "The new policy will effect the way employees report their expenses."', '[{"id":"a","text":"\"report\" should be \"reports\""},{"id":"b","text":"\"their\" should be \"there\""},{"id":"c","text":"No error"},{"id":"d","text":"\"effect\" should be \"affect\""}]'::jsonb, 'd', '"Affect" is the verb (to influence); "effect" is a noun (result). The sentence needs the verb "affect".', 'easy', array['error-identification','commonly-confused-words']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-21', 'writingAnalysis', null, null, null, null, 'Identify the error: "The students must bring his own laptop to the exam."', '[{"id":"a","text":"\"must\" should be \"can\", because the rule is only a suggestion"},{"id":"b","text":"\"his\" should be \"their\", because \"students\" is plural"},{"id":"c","text":"\"bring\" should be \"brought\", because the exam is in the past"},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'b', 'The noun "students" is plural, so the possessive pronoun must be plural too: "their own laptop".', 'medium', array['error-identification','pronoun-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-22', 'writingAnalysis', null, null, null, null, 'Identify the error: "Walking down the street, the building caught my attention."', '[{"id":"a","text":"\"caught\" should be \"catches\", because the sentence describes something happening now"},{"id":"b","text":"\"my\" should be \"mine\", because it stands alone before the noun \"attention\""},{"id":"c","text":"\"Walking down the street\" is a dangling modifier — it describes a person, not \"the building\""},{"id":"d","text":"No error — the sentence is correct as it is written and needs no change"}]'::jsonb, 'c', 'The introductory phrase should modify the person who is walking; "the building" can''t walk, so the modifier dangles.', 'hard', array['error-identification','dangling-modifiers']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-23', 'writingAnalysis', null, null, null, null, 'Identify the error: "She wanted to buy a new car, get a better job, and to move to a bigger apartment."', '[{"id":"a","text":"\"buy\" should be \"bought\", because the plan has already been made"},{"id":"b","text":"\"better\" should be \"more good\", because \"good\" is a long adjective"},{"id":"c","text":"No error — the sentence is correct as it is written"},{"id":"d","text":"\"to move\" breaks the parallel structure — it should be \"move\""}]'::jsonb, 'd', 'Items in a list must be parallel: "to buy, get, and move" — the "to" before "move" breaks the pattern.', 'medium', array['error-identification','parallel-structure']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-24', 'writingAnalysis', null, null, null, null, 'Identify the error: "The team are proud of its achievement this season."', '[{"id":"a","text":"\"are\" should be \"is\" to match the singular subject \"team\" and \"its\""},{"id":"b","text":"\"proud\" should be \"pride\", because it follows the verb \"are\""},{"id":"c","text":"\"its\" should be \"it''s\", because it shows possession"},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'a', '"Team" is treated as a singular collective noun here (matching "its"), so the verb should be "is", not "are".', 'medium', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-25', 'writingAnalysis', null, null, null, null, 'Identify the error: "Me and my brother are going to the match."', '[{"id":"a","text":"\"are going\" should be \"is going\", because \"match\" is singular"},{"id":"b","text":"\"the match\" should be \"a match\", because it is mentioned for the first time"},{"id":"c","text":"\"Me\" should be \"My brother and I\", because it is the subject of the sentence"},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'c', 'A pronoun that is part of the subject takes the subject form: "My brother and I are going to the match."', 'medium', array['error-identification','pronoun-case']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-26', 'writingAnalysis', null, null, null, null, 'Identify the error: "The amount of students who failed the exam increased this year."', '[{"id":"a","text":"\"failed\" should be \"fail\", because \"students\" is plural"},{"id":"b","text":"\"increased\" should be \"increasing\", because the change is ongoing"},{"id":"c","text":"No error — the sentence is correct as it is written"},{"id":"d","text":"\"amount\" should be \"number\" — students are countable"}]'::jsonb, 'd', '"Amount" is used with uncountable nouns; countable items like "students" take "number".', 'easy', array['error-identification','countable-uncountable']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-27', 'writingAnalysis', null, null, null, null, 'Identify the error: "Had he arrived earlier, he would have met the director."', '[{"id":"a","text":"No error"},{"id":"b","text":"\"Had he arrived\" should be \"If he has arrived\""},{"id":"c","text":"\"would have met\" should be \"would meet\""},{"id":"d","text":"\"earlier\" should be \"more early\""}]'::jsonb, 'a', '"Had + subject + past participle" is a correct inverted third conditional: "Had he arrived earlier, he would have met...".', 'hard', array['error-identification','conditionals','inversion']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-28', 'writingAnalysis', null, null, null, null, 'Identify the error: "The manager, as well as the employees, were asked to attend the safety meeting."', '[{"id":"a","text":"\"asked\" should be \"asking\", because it follows the verb \"were\""},{"id":"b","text":"\"were\" should be \"was\" — \"as well as\" doesn''t make the subject plural"},{"id":"c","text":"\"attend\" should be \"attending\", because it follows the word \"to\""},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'b', 'The subject is "the manager" (singular); "as well as the employees" is an added phrase, so the verb stays "was".', 'hard', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-29', 'writingAnalysis', null, null, null, null, 'Identify the error: "He is one of the students who has completed the advanced course."', '[{"id":"a","text":"\"completed\" should be \"completing\", because the action is ongoing"},{"id":"b","text":"\"advanced\" should be \"advancing\", because it describes the course"},{"id":"c","text":"No error — the sentence is correct as it is written"},{"id":"d","text":"\"has\" should be \"have\" — the antecedent of \"who\" is \"students\" (plural)"}]'::jsonb, 'd', 'The relative pronoun "who" refers to "students" (plural), so the verb must be "have completed".', 'hard', array['error-identification','subject-verb-agreement','relative-clauses']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-30', 'writingAnalysis', null, null, null, null, 'Identify the error: "She was supposed to be home by now, but her flight was delay."', '[{"id":"a","text":"\"delay\" should be \"delayed\""},{"id":"b","text":"\"supposed\" should be \"supposing\""},{"id":"c","text":"\"by now\" should be \"until now\""},{"id":"d","text":"No error"}]'::jsonb, 'a', 'After "was", a past participle is needed: "was delayed".', 'easy', array['error-identification','tenses']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-31', 'writingAnalysis', null, null, null, null, 'Identify the error: "If he would have checked the map, he wouldn''t have gotten lost."', '[{"id":"a","text":"\"gotten\" should be \"get\", because it follows the word \"have\""},{"id":"b","text":"\"would have checked\" should be \"had checked\""},{"id":"c","text":"\"the map\" should be \"a map\", because it is mentioned for the first time"},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'b', 'The if-clause of a third conditional uses past perfect: "If he had checked", not "would have checked".', 'hard', array['error-identification','conditionals']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-32', 'writingAnalysis', null, null, null, null, 'Identify the error: "The report include a detailed analysis of the market trends."', '[{"id":"a","text":"\"analysis\" should be \"analyses\", because the report is detailed"},{"id":"b","text":"\"trends\" should be \"trend\", because \"market\" is singular"},{"id":"c","text":"\"include\" should be \"includes\" — \"report\" is singular"},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'c', 'The singular subject "report" requires the third-person singular verb "includes".', 'easy', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-33', 'writingAnalysis', null, null, null, null, 'Identify the error: "Neither of the two proposals seem practical enough to fund."', '[{"id":"a","text":"\"seem\" should be \"seems\""},{"id":"b","text":"\"Neither of\" should be \"Either of\""},{"id":"c","text":"\"practical\" should be \"practically\""},{"id":"d","text":"No error"}]'::jsonb, 'a', '"Neither of" is treated as singular, so the verb must be "seems", not "seem".', 'medium', array['error-identification','subject-verb-agreement']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-34', 'writingAnalysis', null, null, null, null, 'Identify the error: "The lecture was both informative and it was also entertaining."', '[{"id":"a","text":"\"both\" should be \"either\", because two qualities are mentioned"},{"id":"b","text":"\"it was also\" should be \"entertaining\" (parallel structure)"},{"id":"c","text":"\"lecture\" should be \"lecturer\", because a person is described"},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'b', '"Both...and" requires parallel forms: "informative and entertaining" without the repeated "it was also".', 'medium', array['error-identification','parallelism']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-35', 'writingAnalysis', null, null, null, null, 'Identify the error: "Having finished the assignment, the library was a good place to relax."', '[{"id":"a","text":"\"Having finished\" should be \"Finishing\", because the action is still continuing"},{"id":"b","text":"\"relax\" should be \"relaxing\", because it follows the word \"to\" in the sentence"},{"id":"c","text":"\"the library\" should be \"we found the library\" (the opening phrase needs a logical subject)"},{"id":"d","text":"No error — the sentence is correct as it is written and needs no change"}]'::jsonb, 'c', 'The dangling modifier "Having finished the assignment" needs a subject that can finish an assignment — "we" — not "the library".', 'hard', array['error-identification','dangling-modifier']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-36', 'writingAnalysis', null, null, null, null, 'Identify the error: "She did good on the test, so her teacher was very proud."', '[{"id":"a","text":"\"was\" should be \"were\", because the teacher is mentioned with the student"},{"id":"b","text":"\"very\" should be \"much\", because it describes the feeling of pride"},{"id":"c","text":"No error — the sentence is correct as it is written"},{"id":"d","text":"\"good\" should be \"well\", because an adverb is needed after the verb \"did\""}]'::jsonb, 'd', '"Did" is modified by an adverb, not an adjective: "She did well on the test".', 'medium', array['error-identification','adjective-adverb']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-37', 'writingAnalysis', null, null, null, null, 'Identify the error: "The amount of volunteers who signed up was far higher than expected."', '[{"id":"a","text":"\"who\" should be \"which\", because it refers to a group of things"},{"id":"b","text":"\"amount\" should be \"number\" — \"volunteers\" is countable"},{"id":"c","text":"\"higher\" should be \"more high\", because \"high\" is a long adjective"},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'b', '"Volunteers" is a countable noun, so it takes "number of", not "amount of".', 'easy', array['error-identification','countable-uncountable']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-writing-38', 'writingAnalysis', null, null, null, null, 'Identify the error: "Despite of the heavy rain, the match continued without interruption."', '[{"id":"a","text":"\"continued\" should be \"continues\", because the match is still going"},{"id":"b","text":"\"interruption\" should be \"interrupting\", because it follows \"without\""},{"id":"c","text":"\"Despite of\" should be \"Despite\" or \"In spite of\""},{"id":"d","text":"No error — the sentence is correct as it is written"}]'::jsonb, 'c', '"Despite" is used without "of"; the correct alternatives are "Despite the heavy rain" or "In spite of the heavy rain".', 'easy', array['error-identification','prepositions']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-43', 'reading', null, 'passage-dna-genetics', null, null, 'In the passage, the word ''traits'' is closest in meaning to', '[{"id":"a","text":"characteristics"},{"id":"b","text":"serious flaws that make something worse"},{"id":"c","text":"unusual illnesses that spread quickly"},{"id":"d","text":"fixed prices that are set by a shop"}]'::jsonb, 'a', 'The passage uses ''traits such as eye color and height'' to describe distinguishing characteristics of an organism.', 'easy', array['reading-comprehension','vocabulary']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-44', 'reading', null, 'passage-dna-genetics', null, null, 'According to the passage, what can mutations in the genetic code sometimes lead to?', '[{"id":"a","text":"longer lifespans in all cases"},{"id":"b","text":"diseases such as cancer"},{"id":"c","text":"identical twins"},{"id":"d","text":"stronger eyesight"}]'::jsonb, 'b', 'The passage states that ''mutations, or changes in the genetic code, can sometimes lead to diseases such as cancer.''', 'medium', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
