insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-47', 'reading', null, 'passage-space-junk', null, null, 'According to the passage, what could a chain reaction of collisions in orbit eventually cause?', '[{"id":"a","text":"satellites to fall immediately to the ground"},{"id":"b","text":"some orbits to become unusable"},{"id":"c","text":"the moon to change its course"},{"id":"d","text":"space agencies to stop all launches forever"}]'::jsonb, 'b', 'The passage says a chain reaction known as the Kessler syndrome ''could eventually make some orbits unusable.''', 'medium', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
