insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-49', 'reading', null, 'passage-earthquake-safety', null, null, 'In the passage, the word ''sturdy'' is closest in meaning to', '[{"id":"a","text":"strong"},{"id":"b","text":"old"},{"id":"c","text":"wooden"},{"id":"d","text":"glass"}]'::jsonb, 'a', 'Experts advise taking cover under a sturdy table, meaning one that is strong enough to shield the head and neck.', 'easy', array['reading-comprehension','vocabulary']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-50', 'reading', null, 'passage-earthquake-safety', null, null, 'According to the passage, what should people do if they are outdoors during an earthquake?', '[{"id":"a","text":"Run inside the nearest building and shelter there"},{"id":"b","text":"Move to an open area away from buildings, trees, and power lines"},{"id":"c","text":"Stand in a doorway until the shaking stops"},{"id":"d","text":"Get into a car and drive away from the area"}]'::jsonb, 'b', 'The passage advises that people outdoors should ''move to an open area away from buildings, trees, and power lines.''', 'easy', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-51', 'reading', null, 'passage-earthquake-safety', null, null, 'Which of the following best summarizes the passage?', '[{"id":"a","text":"Earthquakes can be predicted precisely and therefore avoided"},{"id":"b","text":"Doorways are the safest places to stand during earthquakes"},{"id":"c","text":"Experts recommend specific actions to reduce the risks posed by earthquakes"},{"id":"d","text":"Only buildings in earthquake zones need emergency kits"}]'::jsonb, 'c', 'The passage centers on safety guidance, from the drop, cover, and hold on technique to preparing emergency kits.', 'medium', array['reading-comprehension','main-idea']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-52', 'reading', null, 'passage-bees-ecosystem', null, null, 'In the passage, the word ''phenomenon'' is closest in meaning to', '[{"id":"a","text":"an imaginary story"},{"id":"b","text":"a type of pesticide"},{"id":"c","text":"a farming method"},{"id":"d","text":"an occurrence or event"}]'::jsonb, 'd', 'The passage calls the sharp decline in bee populations a ''phenomenon scientists refer to as colony collapse disorder'', meaning an observed event.', 'medium', array['reading-comprehension','vocabulary']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-53', 'reading', null, 'passage-bees-ecosystem', null, null, 'According to the passage, which of the following is a factor in the decline of bee populations?', '[{"id":"a","text":"An increase in flowering habitats"},{"id":"b","text":"The use of pesticides"},{"id":"c","text":"Warmer ocean temperatures"},{"id":"d","text":"The introduction of new crops"}]'::jsonb, 'b', 'The passage lists pesticides, loss of habitats, climate change, and the varroa mite as contributing factors to the decline.', 'easy', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-54', 'reading', null, 'passage-bees-ecosystem', null, null, 'What is the main point of the passage?', '[{"id":"a","text":"Bees depend on humans for all of their food"},{"id":"b","text":"All insects are dangerous to crops"},{"id":"c","text":"Bees are vital to food production and are now at risk"},{"id":"d","text":"Colony collapse disorder affects only wild plants"}]'::jsonb, 'c', 'The passage explains bees'' importance as pollinators, describes their decline, and outlines conservation efforts.', 'medium', array['reading-comprehension','main-idea']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
