insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-56', 'reading', null, 'passage-paper-making', null, null, 'According to the passage, what change did the industrial revolution bring to paper production?', '[{"id":"a","text":"Machines could produce long continuous sheets at lower cost"},{"id":"b","text":"Paper was made only from cotton rags"},{"id":"c","text":"Paper became available only to wealthy families"},{"id":"d","text":"The technique spread from Europe to China"}]'::jsonb, 'a', 'The passage states that the industrial revolution brought machines ''that could produce long continuous sheets, lowering costs.''', 'medium', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-57', 'reading', null, 'passage-paper-making', null, null, 'What is the passage mainly about?', '[{"id":"a","text":"The environmental problems caused by recycling old paper"},{"id":"b","text":"The many uses of digital documents in modern offices today"},{"id":"c","text":"How paper spread from China and developed into a modern industry"},{"id":"d","text":"Why wood pulp is rarely used in modern paper factories"}]'::jsonb, 'c', 'The passage traces paper from its invention in China through the Middle East and Europe to modern industrial production.', 'medium', array['reading-comprehension','main-idea']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-58', 'reading', null, 'passage-king-fahd-causeway', null, null, 'In the passage, the word ''periodic'' is closest in meaning to', '[{"id":"a","text":"causing serious damage to buildings and roads"},{"id":"b","text":"extremely expensive for most ordinary people"},{"id":"c","text":"lasting forever without any change at all"},{"id":"d","text":"happening at regular intervals"}]'::jsonb, 'd', 'The passage notes the causeway ''has required periodic maintenance'', meaning maintenance carried out regularly from time to time.', 'medium', array['reading-comprehension','vocabulary']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
