insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-60', 'reading', null, 'passage-king-fahd-causeway', null, null, 'What is the main purpose of the passage?', '[{"id":"a","text":"To compare the economies of Saudi Arabia and Bahrain"},{"id":"b","text":"To describe the King Fahd Causeway and its importance"},{"id":"c","text":"To explain how ferries are built"},{"id":"d","text":"To argue against road travel across the Gulf"}]'::jsonb, 'b', 'The passage describes the causeway''s construction, design, opening, and its economic and travel impact.', 'medium', array['reading-comprehension','main-idea']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-61', 'reading', null, 'passage-ibn-sina', null, null, 'In the passage, the word ''overturned'' is closest in meaning to', '[{"id":"a","text":"supported"},{"id":"b","text":"translated"},{"id":"c","text":"reprinted"},{"id":"d","text":"disproved"}]'::jsonb, 'd', 'The passage says some of Ibn Sina''s theories ''were later overturned by modern science'', meaning they were disproved or replaced.', 'hard', array['reading-comprehension','vocabulary']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-62', 'reading', null, 'passage-ibn-sina', null, null, 'According to the passage, how was the Canon of Medicine used in Europe?', '[{"id":"a","text":"As a standard medical textbook in universities for over five hundred years"},{"id":"b","text":"As a book of poetry that was read aloud to children in many schools"},{"id":"c","text":"As a guide for sea navigation that was used by ship captains for centuries"},{"id":"d","text":"As a history of Islamic philosophy that was studied by students in Europe"}]'::jsonb, 'a', 'The passage states the Canon of Medicine ''was used as a standard textbook in European universities for over five hundred years.''', 'easy', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-63', 'reading', null, 'passage-ibn-sina', null, null, 'Which statement best reflects the author''s view of Ibn Sina?', '[{"id":"a","text":"His medical ideas were completely wrong and soon forgotten"},{"id":"b","text":"He was a significant figure whose work shaped medicine and learning"},{"id":"c","text":"He was important only in his own country and nowhere else"},{"id":"d","text":"His philosophy had no influence outside the continent of Asia"}]'::jsonb, 'b', 'The passage describes him as a pioneer whose Canon of Medicine was used for centuries and whose writings spread widely across Europe and Asia.', 'hard', array['reading-comprehension','author-opinion']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-64', 'reading', null, 'passage-ice-cream-history', null, null, 'In the passage, the word ''elaborate'' is closest in meaning to', '[{"id":"a","text":"simple and plain, without any decoration"},{"id":"b","text":"inexpensive and easy for everyone to afford"},{"id":"c","text":"carefully arranged and fancy"},{"id":"d","text":"religious and used only in places of worship"}]'::jsonb, 'c', 'The passage describes ice cream being served at ''elaborate banquets'', meaning grand and carefully arranged occasions.', 'medium', array['reading-comprehension','vocabulary']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-65', 'reading', null, 'passage-ice-cream-history', null, null, 'According to the passage, what made ice cream accessible to ordinary people?', '[{"id":"a","text":"Improvements in refrigeration and the invention of mechanical freezing machines"},{"id":"b","text":"The invention of the waffle cone in Italy during the early twentieth century"},{"id":"c","text":"The arrival of the dessert in New York harbor on large trading ships"},{"id":"d","text":"Trade routes between China and Europe in ancient times, which carried the recipes"}]'::jsonb, 'a', 'The passage says improvements in refrigeration and mechanical freezing machines allowed large-scale production that made it affordable.', 'easy', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-66', 'reading', null, 'passage-ice-cream-history', null, null, 'What is the passage mainly about?', '[{"id":"a","text":"How to prepare ice cream at home using simple tools and fresh fruit"},{"id":"b","text":"The development of ice cream from ancient chilled desserts to a global industry"},{"id":"c","text":"The dangers of eating cold desserts in winter and how to avoid them"},{"id":"d","text":"A comparison between Chinese and Italian cooking methods through history"}]'::jsonb, 'b', 'The passage traces ice cream from ancient flavored ices through European nobility to modern global production.', 'medium', array['reading-comprehension','main-idea']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
