insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-68', 'reading', null, 'passage-internet-saudi-arabia', null, null, 'According to the passage, when was the public internet officially launched in Saudi Arabia?', '[{"id":"a","text":"In the mid-1990s"},{"id":"b","text":"In 1982"},{"id":"c","text":"After mobile networks were introduced"},{"id":"d","text":"In 1999"}]'::jsonb, 'd', 'The passage states that the public internet was officially launched in 1999.', 'easy', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-69', 'reading', null, 'passage-internet-saudi-arabia', null, null, 'Which of the following best summarizes the passage?', '[{"id":"a","text":"The internet failed to attract many users in Saudi Arabia for many years and later disappeared"},{"id":"b","text":"The internet in Saudi Arabia was introduced carefully and then spread rapidly with broad social effects"},{"id":"c","text":"Academic networks were the only way that anyone in the kingdom could ever use the internet"},{"id":"d","text":"The government banned the internet for a long period of time and then allowed it again"}]'::jsonb, 'b', 'The passage describes a planned introduction, rapid growth of users, and wide social impact across communication, study, and services.', 'medium', array['reading-comprehension','main-idea']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-70', 'reading', null, 'passage-wwii-impact', null, null, 'In the passage, the word ''redrew'' is closest in meaning to', '[{"id":"a","text":"painted"},{"id":"b","text":"ignored"},{"id":"c","text":"changed"},{"id":"d","text":"copied"}]'::jsonb, 'c', 'The passage says the war ''redrew borders'', meaning it altered or changed the boundaries of countries.', 'hard', array['reading-comprehension','vocabulary']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-71', 'reading', null, 'passage-wwii-impact', null, null, 'According to the passage, which international organization was established in 1945 as a result of the war?', '[{"id":"a","text":"The League of Nations"},{"id":"b","text":"The European Union"},{"id":"c","text":"The International Red Cross"},{"id":"d","text":"The United Nations"}]'::jsonb, 'd', 'The passage states that the war led to the establishment of the United Nations in 1945.', 'easy', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-72', 'reading', null, 'passage-wwii-impact', null, null, 'What is the passage mainly about?', '[{"id":"a","text":"The political, technological, and social consequences of World War II"},{"id":"b","text":"The military strategies used by the main armies during the war"},{"id":"c","text":"The biographies of famous soldiers who fought in the war"},{"id":"d","text":"The reconstruction of Japan after the war alone"}]'::jsonb, 'a', 'The passage covers the war''s human cost, technological changes, the founding of the UN, and its lasting political effects.', 'medium', array['reading-comprehension','main-idea']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
