insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-reading-74', 'reading', null, 'passage-istanbul-history', null, null, 'According to the passage, what happened to the city in 1453?', '[{"id":"a","text":"It was renamed Constantinople by the Roman emperor"},{"id":"b","text":"It became the capital of the Turkish Republic"},{"id":"c","text":"It was destroyed by a great fire that lasted a week"},{"id":"d","text":"It was captured by the Ottomans under Sultan Mehmed II"}]'::jsonb, 'd', 'The passage states that Ottoman forces under Sultan Mehmed II captured the city in 1453.', 'easy', array['reading-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
