insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-75', 'listening', null, null, '/audio/listening/q-listening-75.mp3', 'Student: Professor, I can''t finish all my assignments on time. There is simply never enough time.
Professor: Let me see your weekly schedule. How many hours do you manage to study each day?
Student: About three hours, but I waste an hour on my phone every evening.
Professor: Then the problem is not a lack of time. Plan your day the night before, and study only two subjects a day, with a ten minute break between them.
Student: Okay, I''ll start planning tonight and limit my phone time to half an hour.', 'How much time does the student waste on his phone every evening?', '[{"id":"a","text":"About one hour"},{"id":"b","text":"About thirty minutes"},{"id":"c","text":"About two hours"},{"id":"d","text":"About three hours"}]'::jsonb, 'a', 'The student says, "I waste an hour on my phone every evening."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
