insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-78', 'listening', null, null, '/audio/listening/q-listening-78.mp3', 'Salesperson: Good evening, Pizza Palace. We have two special offers tonight: a large pizza with one topping for thirty riyals, or two medium pizzas for fifty riyals.
Man: We are only three people, so one large is not enough, and two mediums seem like a lot.
Salesperson: Then how about a large pizza with two toppings for thirty-five riyals? It is big enough for four people.
Man: That sounds better. Do you deliver to Al-Noor Street?
Salesperson: Yes, delivery is free tonight for any order over thirty riyals.
Man: Great, I will take the large pizza with two toppings, please.', 'How much does the large pizza with two toppings cost?', '[{"id":"a","text":"Thirty-five riyals"},{"id":"b","text":"Thirty riyals for the large pizza with two toppings"},{"id":"c","text":"Fifty riyals for the large pizza with two toppings"},{"id":"d","text":"Forty riyals for the large pizza with two toppings"}]'::jsonb, 'a', 'The salesperson offers "a large pizza with two toppings for thirty-five riyals."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
