insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('q-listening-81', 'listening', null, null, '/audio/listening/q-listening-81.mp3', 'Man: You''ve been a teacher for ten years now. What made you choose this profession in the first place?
Woman: Honestly, my high school English teacher inspired me. She made every lesson interesting.
Man: Is the salary as low as people say?
Woman: The salary is average, but I get long holidays and a short working day. For me, the flexible hours matter more.
Man: Would you still choose teaching if you could start again?
Woman: Without a doubt. I feel I make a real difference in my students'' lives every single day.', 'Who inspired the woman to become a teacher?', '[{"id":"a","text":"Her high school English teacher"},{"id":"b","text":"Her mother, who worked as a teacher for years"},{"id":"c","text":"A colleague at work, who taught her to enjoy lessons"},{"id":"d","text":"A famous writer whose books she read at school"}]'::jsonb, 'a', 'The woman says, "my high school English teacher inspired me."', 'easy', array['listening-comprehension']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
