insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm-listening-10', 'listening', null, null, null, 'Customer: Good morning. I heard you are running special offers at the moment.
Seller: Good morning, sir. Yes, we have a different special offer every day.
Customer: What is today''s offer?
Seller: Today''s offer costs only $65. For that price, you get two medium pizzas and two cans of soda.
Customer: That sounds like a great deal. I''ll take it.
Seller: What kind of pizza would you like?
Customer: Two pepperoni pizzas, please.
Seller: Sure. Your pizzas and soda will be ready to pick up in about an hour from Jack''s Pizza Place.
Customer: Wonderful. Thank you very much.
Seller: You''re most welcome.', 'How much does today''s special offer cost?', '[{"id":"a","text":"Twenty-five dollars"},{"id":"b","text":"Fifty dollars"},{"id":"c","text":"Ninety-five dollars"},{"id":"d","text":"Sixty-five dollars"}]'::jsonb, 'd', 'The seller says today''s offer costs $65, which includes two medium pizzas and two cans of soda.', 'easy', array['listening-comprehension','step-mock']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
