insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-17', 'reading', null, 'passage-sm2-5', null, null, 'In the passage, the word ''mature'' is closest in meaning to', '[{"id":"a","text":"fully grown"},{"id":"b","text":"very old"},{"id":"c","text":"newly planted"},{"id":"d","text":"badly damaged"}]'::jsonb, 'a', 'A mature tree is one that has grown enough to produce a full crop.', 'easy', array['reading-comprehension','vocabulary','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-18', 'reading', null, 'passage-sm2-5', null, null, 'According to the passage, how do date palms help the environment?', '[{"id":"a","text":"They reduce the amount of rain that falls on the oasis."},{"id":"b","text":"Their shade protects smaller crops from the sun."},{"id":"c","text":"They remove salt from the sea water near the coast."},{"id":"d","text":"They attract tourists to the desert every year."}]'::jsonb, 'b', 'The passage says their shade protects smaller crops from the harsh sun (and their roots hold the soil).', 'medium', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-19', 'reading', null, 'passage-sm2-5', null, null, 'In the passage, ''they'' in the last sentence refers to', '[{"id":"a","text":"varieties"},{"id":"b","text":"guests"},{"id":"c","text":"families"},{"id":"d","text":"oases"}]'::jsonb, 'c', '''Many families still have a favourite that they serve to guests'' - the families do the serving.', 'medium', array['reading-comprehension','pronoun-reference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-20', 'reading', null, 'passage-sm2-5', null, null, 'The passage is mainly about', '[{"id":"a","text":"how to grow dates successfully in a home garden"},{"id":"b","text":"the history of Bedouin travel across the desert"},{"id":"c","text":"the export of dates to countries abroad"},{"id":"d","text":"the many uses and importance of the date palm"}]'::jsonb, 'd', 'Each paragraph describes a use or benefit of the date palm.', 'easy', array['reading-comprehension','main-idea','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-21', 'reading', null, 'passage-sm2-6', null, null, 'In the passage, the word ''intruder'' is closest in meaning to', '[{"id":"a","text":"a helpful visitor who is welcome in the body"},{"id":"b","text":"something that enters where it does not belong"},{"id":"c","text":"a type of medicine that fights germs"},{"id":"d","text":"a protective cell that guards the body"}]'::jsonb, 'b', 'The immune system recognises the germ as foreign, something that enters the body where it does not belong.', 'medium', array['reading-comprehension','vocabulary','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-22', 'reading', null, 'passage-sm2-6', null, null, 'Why do some vaccines need booster doses?', '[{"id":"a","text":"The germs change every year."},{"id":"b","text":"Babies cannot receive the first dose."},{"id":"c","text":"The body''s memory of the germ fades over time."},{"id":"d","text":"Antibodies turn into memory cells."}]'::jsonb, 'c', 'The passage says some vaccines need boosters ''because the memory fades over time''.', 'medium', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-23', 'reading', null, 'passage-sm2-6', null, null, 'In the passage, ''this'' in ''and this protects even those who cannot be vaccinated'' refers to', '[{"id":"a","text":"memory cells staying in the blood"},{"id":"b","text":"the vaccine containing a weakened germ"},{"id":"c","text":"the immune system making antibodies"},{"id":"d","text":"most people in a community being vaccinated"}]'::jsonb, 'd', 'The sentence says that when most people are vaccinated the disease struggles to spread, and this protects the others.', 'hard', array['reading-comprehension','pronoun-reference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-24', 'reading', null, 'passage-sm2-6', null, null, 'What can be inferred about smallpox from the passage?', '[{"id":"a","text":"Vaccination can remove a disease from the world."},{"id":"b","text":"It still kills millions today."},{"id":"c","text":"It was the first disease ever studied."},{"id":"d","text":"It never required booster doses."}]'::jsonb, 'a', 'Smallpox was ''completely wiped out in 1980 through worldwide vaccination'', so vaccination can eliminate a disease.', 'medium', array['reading-comprehension','inference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-25', 'reading', null, 'passage-sm2-7', null, null, 'In the passage, the word ''adopted'' is closest in meaning to', '[{"id":"a","text":"refused to accept"},{"id":"b","text":"forgot about completely"},{"id":"c","text":"started to use"},{"id":"d","text":"argued about openly"}]'::jsonb, 'c', 'Most countries gradually began using the time-zone system.', 'easy', array['reading-comprehension','vocabulary','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-26', 'reading', null, 'passage-sm2-7', null, null, 'Why did railways make local sun time a problem?', '[{"id":"a","text":"Trains were too fast for passengers to measure the time."},{"id":"b","text":"Clocks stopped working when they were near the tracks."},{"id":"c","text":"Travellers did not trust the new trains and avoided them."},{"id":"d","text":"Stations kept different times, which confused timetables."}]'::jsonb, 'd', 'Timetables became confusing because two stations kept different times.', 'easy', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-27', 'reading', null, 'passage-sm2-7', null, null, 'In the passage, ''This'' in ''This caused little trouble until railways appeared'' refers to', '[{"id":"a","text":"each town using its own local time"},{"id":"b","text":"the meeting held in Washington"},{"id":"c","text":"the invention of the clock"},{"id":"d","text":"the distance between cities"}]'::jsonb, 'a', 'The previous sentence says every town set its clocks by the sun, so times differed from place to place.', 'medium', array['reading-comprehension','pronoun-reference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-28', 'reading', null, 'passage-sm2-7', null, null, 'What is the author''s main purpose in the passage?', '[{"id":"a","text":"To compare the clocks of China with those of Saudi Arabia"},{"id":"b","text":"To explain how and why standard time zones were created"},{"id":"c","text":"To criticise the railway companies for causing confusion"},{"id":"d","text":"To describe the long history of the town of Greenwich"}]'::jsonb, 'b', 'The passage moves from local sun time to the 1884 agreement and the system we use today.', 'medium', array['reading-comprehension','main-idea','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-29', 'reading', null, 'passage-sm2-8', null, null, 'In the passage, the word ''scarce'' is closest in meaning to', '[{"id":"a","text":"dangerous to eat"},{"id":"b","text":"plentiful and cheap"},{"id":"c","text":"tasty and sweet"},{"id":"d","text":"hard to find"}]'::jsonb, 'd', 'Camels use stored fat when food is scarce, meaning when it is not easy to find.', 'easy', array['reading-comprehension','vocabulary','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-30', 'reading', null, 'passage-sm2-8', null, null, 'According to the passage, what does a camel''s hump store?', '[{"id":"a","text":"Fat"},{"id":"b","text":"Water"},{"id":"c","text":"Milk"},{"id":"d","text":"Sand"}]'::jsonb, 'a', 'The passage corrects the popular belief: the hump stores fat, not water.', 'easy', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-31', 'reading', null, 'passage-sm2-8', null, null, 'In the passage, ''it'' in ''it can then travel for days'' refers to', '[{"id":"a","text":"the water"},{"id":"b","text":"the camel"},{"id":"c","text":"the hump"},{"id":"d","text":"the desert"}]'::jsonb, 'b', '''A camel can drink... and it can then travel for days without drinking.''', 'easy', array['reading-comprehension','pronoun-reference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-32', 'reading', null, 'passage-sm2-8', null, null, 'Which statement best reflects the author''s view of camels?', '[{"id":"a","text":"They are no longer useful to anyone in the modern region."},{"id":"b","text":"They are dangerous to travellers who cross the desert."},{"id":"c","text":"They are admirable animals that are still valued in the region."},{"id":"d","text":"They are difficult to breed and expensive to keep."}]'::jsonb, 'c', 'The author praises their design and calls them a proud symbol that is still raced and bred.', 'medium', array['reading-comprehension','author-opinion','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-33', 'reading', null, 'passage-sm2-9', null, null, 'In the passage, the word ''influential'' is closest in meaning to', '[{"id":"a","text":"having a strong effect on others"},{"id":"b","text":"hard to understand for most people"},{"id":"c","text":"very old and no longer used"},{"id":"d","text":"easy to carry from place to place"}]'::jsonb, 'a', 'Ranking the press among history''s most influential inventions means it had a great effect on the world.', 'medium', array['reading-comprehension','vocabulary','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-34', 'reading', null, 'passage-sm2-9', null, null, 'Why were books so expensive before the printing press?', '[{"id":"a","text":"Paper was extremely rare and had to be imported."},{"id":"b","text":"They were copied by hand, which took months."},{"id":"c","text":"Kings taxed them heavily whenever they were sold."},{"id":"d","text":"Few people could write well enough to copy them."}]'::jsonb, 'b', 'Copying a single volume by hand could take a monk many months.', 'easy', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-35', 'reading', null, 'passage-sm2-9', null, null, 'In the passage, ''they'' in ''because they could no longer control what people read'' refers to', '[{"id":"a","text":"scientists"},{"id":"b","text":"families"},{"id":"c","text":"rulers"},{"id":"d","text":"monks"}]'::jsonb, 'c', '''Some rulers feared the new technology because they could no longer control...''', 'easy', array['reading-comprehension','pronoun-reference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-36', 'reading', null, 'passage-sm2-9', null, null, 'What can be inferred about the effect of cheaper books?', '[{"id":"a","text":"Fewer people learned to read as books became common."},{"id":"b","text":"Churches became much richer than they were before."},{"id":"c","text":"Handwriting disappeared at once from every country."},{"id":"d","text":"More people were able to learn and share ideas."}]'::jsonb, 'd', 'Prices fell, literacy rose, and ideas and discoveries travelled faster.', 'medium', array['reading-comprehension','inference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-37', 'reading', null, 'passage-sm2-10', null, null, 'In the passage, the word ''ideal'' is closest in meaning to', '[{"id":"a","text":"rather unusual"},{"id":"b","text":"most suitable"},{"id":"c","text":"very distant"},{"id":"d","text":"quite dangerous"}]'::jsonb, 'b', 'Strong sunlight makes the peninsula the most suitable place for solar farms.', 'easy', array['reading-comprehension','vocabulary','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-38', 'reading', null, 'passage-sm2-10', null, null, 'According to the passage, why are better batteries being developed?', '[{"id":"a","text":"Panels are too expensive for most families to buy."},{"id":"b","text":"Panels are too noisy for use near houses."},{"id":"c","text":"Panels produce no electricity at night."},{"id":"d","text":"Panels need extra fuel in order to work properly."}]'::jsonb, 'c', 'Panels produce nothing at night, so extra daytime energy must be stored.', 'easy', array['reading-comprehension','detail','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-39', 'reading', null, 'passage-sm2-10', null, null, 'In the passage, ''them'' in ''rather than replace them'' refers to', '[{"id":"a","text":"the solar panels themselves"},{"id":"b","text":"the batteries in cars"},{"id":"c","text":"the engineers who work on them"},{"id":"d","text":"other energy sources"}]'::jsonb, 'd', 'Solar power will work alongside other sources rather than replace those sources.', 'medium', array['reading-comprehension','pronoun-reference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-reading-40', 'reading', null, 'passage-sm2-10', null, null, 'What is the author''s view of the future of solar power?', '[{"id":"a","text":"It will grow but probably work alongside other sources."},{"id":"b","text":"It will end the need for every other kind of energy."},{"id":"c","text":"It will remain limited to Saudi Arabia for many years."},{"id":"d","text":"It is too expensive to continue developing."}]'::jsonb, 'a', 'The author is positive about solar power but says it will probably not replace other sources until storage improves.', 'hard', array['reading-comprehension','author-opinion','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
