insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-grammar-3', 'grammar', null, null, null, null, 'We don''t have ___ information about the trip yet.', '[{"id":"a","text":"many"},{"id":"b","text":"a few"},{"id":"c","text":"much"},{"id":"d","text":"several"}]'::jsonb, 'c', '''Information'' is uncountable, so it takes ''much'' in a negative sentence.', 'easy', array['countable-uncountable','quantifiers','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
