insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-grammar-25', 'grammar', null, null, null, null, 'We ___ play football in the street when we were children.', '[{"id":"a","text":"use to"},{"id":"b","text":"are used to"},{"id":"c","text":"used to"},{"id":"d","text":"were used to"}]'::jsonb, 'c', '''Used to'' + base verb describes a past habit that no longer continues.', 'medium', array['used-to','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
