insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-grammar-29', 'grammar', null, null, null, null, 'She wants to be ___ engineer like her father.', '[{"id":"a","text":"a"},{"id":"b","text":"the"},{"id":"c","text":"some"},{"id":"d","text":"an"}]'::jsonb, 'd', 'Use ''an'' before a vowel sound.', 'easy', array['articles','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-grammar-30', 'grammar', null, null, null, null, 'Not only ___ the exam, but he also got the highest mark.', '[{"id":"a","text":"did he pass"},{"id":"b","text":"he passed"},{"id":"c","text":"he did pass"},{"id":"d","text":"passed he"}]'::jsonb, 'a', 'After ''Not only'' at the start, the auxiliary comes before the subject: did he pass.', 'hard', array['inversion','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-1', 'listening', null, null, '/audio/listening/sm2-listening-1.mp3', 'Clerk: Good morning. How can I help you?
Student: Hi. I''d like to register for the evening English course that starts next month.
Clerk: Of course. The course meets on Sundays and Tuesdays from six to eight. The registration fee is four hundred and fifty riyals.
Student: Is it possible to pay in two parts?
Clerk: Yes, you can pay half now and half before the third week. But registration closes this Thursday, so please don''t wait too long.
Student: That''s fine. Do I need to bring anything?
Clerk: A copy of your ID and one passport-size photo. You can email the ID copy if you prefer.
Student: Great. I''ll come back tomorrow with the photo and pay the first half then.
Clerk: Perfect. See you tomorrow.', 'On which days does the course meet?', '[{"id":"a","text":"Sundays and Tuesdays"},{"id":"b","text":"Mondays and Wednesdays"},{"id":"c","text":"Thursdays and Fridays"},{"id":"d","text":"Every weekday"}]'::jsonb, 'a', 'The clerk says the course meets on Sundays and Tuesdays from six to eight.', 'easy', array['listening-comprehension','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-2', 'listening', null, null, '/audio/listening/sm2-listening-1.mp3', 'Clerk: Good morning. How can I help you?
Student: Hi. I''d like to register for the evening English course that starts next month.
Clerk: Of course. The course meets on Sundays and Tuesdays from six to eight. The registration fee is four hundred and fifty riyals.
Student: Is it possible to pay in two parts?
Clerk: Yes, you can pay half now and half before the third week. But registration closes this Thursday, so please don''t wait too long.
Student: That''s fine. Do I need to bring anything?
Clerk: A copy of your ID and one passport-size photo. You can email the ID copy if you prefer.
Student: Great. I''ll come back tomorrow with the photo and pay the first half then.
Clerk: Perfect. See you tomorrow.', 'When does registration close?', '[{"id":"a","text":"Tomorrow"},{"id":"b","text":"This Thursday"},{"id":"c","text":"Next month"},{"id":"d","text":"Before the third week"}]'::jsonb, 'b', 'The clerk warns that registration closes this Thursday.', 'easy', array['listening-comprehension','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
