insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-7', 'listening', null, null, '/audio/listening/sm2-listening-7.mp3', 'Receptionist: Dr. Hassan''s clinic, how can I help?
Caller: Hello, this is Khalid Omar. I have an appointment on Monday at ten, but I''m afraid I have to change it. My brother is getting married and I''ll be travelling.
Receptionist: I see. Congratulations! Would Wednesday at half past four work?
Caller: Wednesday is fine, but I finish work at four and the clinic is far from my office. Could we make it five o''clock?
Receptionist: Let me check... yes, five o''clock is free on Wednesday.
Caller: Perfect. Thank you.
Receptionist: I''ll send you a text message to confirm.', 'Why does the caller want to change his appointment?', '[{"id":"a","text":"He is feeling much better and does not need it."},{"id":"b","text":"He has an important meeting at his work."},{"id":"c","text":"The clinic is closed on Monday morning."},{"id":"d","text":"He will travel for his brother''s wedding."}]'::jsonb, 'd', 'He says his brother is getting married and he will be travelling.', 'easy', array['listening-comprehension','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
