insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-11', 'listening', null, null, '/audio/listening/sm2-listening-11.mp3', 'Announcement: Attention please, passengers travelling to Cairo on flight two-one-eight. Due to a technical check, your flight is now delayed by forty minutes. The original departure time was ten thirty, so the new departure time is ten past eleven. Please note that the gate has also changed from gate twelve to gate twenty. Passengers who would like a meal may collect a free voucher from the information desk near gate fifteen. We apologise for the inconvenience.', 'What is the new departure time?', '[{"id":"a","text":"11:10"},{"id":"b","text":"10:30"},{"id":"c","text":"11:00"},{"id":"d","text":"11:40"}]'::jsonb, 'a', 'The flight was due at 10:30 and is delayed by forty minutes, so it leaves at ten past eleven.', 'medium', array['listening-comprehension','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-12', 'listening', null, null, '/audio/listening/sm2-listening-11.mp3', 'Announcement: Attention please, passengers travelling to Cairo on flight two-one-eight. Due to a technical check, your flight is now delayed by forty minutes. The original departure time was ten thirty, so the new departure time is ten past eleven. Please note that the gate has also changed from gate twelve to gate twenty. Passengers who would like a meal may collect a free voucher from the information desk near gate fifteen. We apologise for the inconvenience.', 'How can passengers get a free meal voucher?', '[{"id":"a","text":"Show their tickets at the desk by gate twenty"},{"id":"b","text":"Go to the information desk near gate fifteen"},{"id":"c","text":"Call the airline from the departure hall"},{"id":"d","text":"Wait at gate twelve for an announcement"}]'::jsonb, 'b', 'The announcement says vouchers are available from the information desk near gate fifteen.', 'easy', array['listening-comprehension','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-13', 'listening', null, null, '/audio/listening/sm2-listening-13.mp3', 'Librarian: Welcome to the university library. You can borrow up to five books at a time for two weeks. If you need more time, you can renew them once online, unless someone else has reserved them. Late books cost one riyal per day.
Student: What about reference books, like dictionaries?
Librarian: Those can''t leave the library, but you can photocopy a few pages.
Student: And the quiet study rooms?
Librarian: They must be booked in advance at the desk, and you can use a room for a maximum of two hours.', 'What is the rule about reference books?', '[{"id":"a","text":"They can be borrowed for two weeks."},{"id":"b","text":"They cost one riyal per day."},{"id":"c","text":"They must be booked in advance."},{"id":"d","text":"They cannot be taken out of the library."}]'::jsonb, 'd', 'The librarian says reference books can''t leave the library, though pages can be photocopied.', 'easy', array['listening-comprehension','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
