insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-15', 'listening', null, null, '/audio/listening/sm2-listening-15.mp3', 'Professor: Today I''d like to talk about coffee. According to legend, coffee was discovered in Ethiopia, when a goat herder noticed that his goats became very energetic after eating the berries of a certain bush. By the fifteenth century coffee was being grown in Yemen, and from there it spread through the Arabian Peninsula to Cairo, Istanbul and eventually Europe. In Makkah and other cities, coffee houses became popular meeting places where people discussed the news and played chess. Some rulers were suspicious of these houses, fearing that people would talk about politics, and they tried to ban them. Of course, the bans did not last, because coffee was simply too popular.', 'According to the legend, how was coffee discovered?', '[{"id":"a","text":"Monks tested it as a medicine for tired travellers."},{"id":"b","text":"A herder noticed his goats'' energy after they ate berries."},{"id":"c","text":"Travellers found it growing wild in Yemen."},{"id":"d","text":"A king ordered his servants to search for it."}]'::jsonb, 'b', 'The legend says a goat herder noticed that his goats became energetic after eating the berries.', 'medium', array['listening-comprehension','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-16', 'listening', null, null, '/audio/listening/sm2-listening-15.mp3', 'Professor: Today I''d like to talk about coffee. According to legend, coffee was discovered in Ethiopia, when a goat herder noticed that his goats became very energetic after eating the berries of a certain bush. By the fifteenth century coffee was being grown in Yemen, and from there it spread through the Arabian Peninsula to Cairo, Istanbul and eventually Europe. In Makkah and other cities, coffee houses became popular meeting places where people discussed the news and played chess. Some rulers were suspicious of these houses, fearing that people would talk about politics, and they tried to ban them. Of course, the bans did not last, because coffee was simply too popular.', 'Why did some rulers dislike coffee houses?', '[{"id":"a","text":"The houses were too noisy for the neighbours."},{"id":"b","text":"Coffee was far too expensive for most people."},{"id":"c","text":"They feared people would discuss politics."},{"id":"d","text":"Playing chess in the houses was forbidden."}]'::jsonb, 'c', 'Some rulers were suspicious, fearing that people would talk about politics.', 'medium', array['listening-comprehension','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-17', 'listening', null, null, '/audio/listening/sm2-listening-15.mp3', 'Professor: Today I''d like to talk about coffee. According to legend, coffee was discovered in Ethiopia, when a goat herder noticed that his goats became very energetic after eating the berries of a certain bush. By the fifteenth century coffee was being grown in Yemen, and from there it spread through the Arabian Peninsula to Cairo, Istanbul and eventually Europe. In Makkah and other cities, coffee houses became popular meeting places where people discussed the news and played chess. Some rulers were suspicious of these houses, fearing that people would talk about politics, and they tried to ban them. Of course, the bans did not last, because coffee was simply too popular.', 'What does the professor imply about the bans?', '[{"id":"a","text":"They failed because people loved coffee."},{"id":"b","text":"They were completely successful."},{"id":"c","text":"They were never announced."},{"id":"d","text":"They applied only in Europe."}]'::jsonb, 'a', 'He says the bans did not last because coffee was too popular.', 'hard', array['listening-comprehension','listening-inference','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-listening-18', 'listening', null, null, '/audio/listening/sm2-listening-18.mp3', 'Ali: So, are we all going to the desert camp on Friday?
Faisal: Yes, but I checked the forecast, and it will be very windy, so I think Saturday is better.
Ali: Saturday? I can''t, I have football training in the afternoon.
Faisal: Training starts at four, right? We can leave in the morning and be back by three.
Ali: Hmm, that''s tight, but all right. Who''s bringing the tent?
Faisal: My uncle has a big one, and he said we can borrow it. You bring the food, and Majed will bring the stove.
Ali: Okay. I''ll buy sandwiches and fruit.
Faisal: And don''t forget water!
Ali: Of course.', 'When will the friends go to the camp?', '[{"id":"a","text":"On Friday"},{"id":"b","text":"On Saturday morning"},{"id":"c","text":"On Saturday evening"},{"id":"d","text":"On Sunday"}]'::jsonb, 'b', 'Faisal moves the trip from Friday to Saturday because of wind and suggests leaving in the morning.', 'medium', array['listening-comprehension','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
