insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm2-writing-5', 'writingAnalysis', null, null, null, null, 'Identify the error: "She doesn''t has any brothers or sisters."', '[{"id":"a","text":"\"doesn''t\" should be \"don''t\""},{"id":"b","text":"\"has\" should be \"have\""},{"id":"c","text":"\"any\" should be \"some\""},{"id":"d","text":"\"or\" should be \"and\""}]'::jsonb, 'b', 'After ''does/doesn''t'' the main verb is in the base form: have.', 'medium', array['error-identification','tenses','step-mock-2']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
