insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-16', 'reading', null, 'passage-sm3-4', null, null, 'What is the main purpose of the passage?', '[{"id":"a","text":"To advertise a password manager"},{"id":"b","text":"To describe how criminals are caught"},{"id":"c","text":"To explain how to protect online accounts"},{"id":"d","text":"To compare different phones"}]'::jsonb, 'c', 'Every paragraph gives a way to keep accounts safe.', 'medium', array['reading-comprehension','main-idea','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-17', 'reading', null, 'passage-sm3-5', null, null, 'In the passage, the word ''restored'' is closest in meaning to', '[{"id":"a","text":"repaired to its earlier condition"},{"id":"b","text":"sold to a new owner for money"},{"id":"c","text":"removed from the city centre"},{"id":"d","text":"painted a new colour by artists"}]'::jsonb, 'a', 'Restored palaces have been repaired so that they look as they did originally.', 'medium', array['reading-comprehension','vocabulary','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-18', 'reading', null, 'passage-sm3-5', null, null, 'According to the passage, why was mud brick used in Najdi buildings?', '[{"id":"a","text":"It was cheaper than stone in the city."},{"id":"b","text":"It keeps interiors cool in the summer heat."},{"id":"c","text":"It allowed buildings to be taller."},{"id":"d","text":"It protected the city against floods."}]'::jsonb, 'b', 'The passage says mud brick ''keeps interiors cool in the summer heat''.', 'easy', array['reading-comprehension','detail','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
