insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-20', 'reading', null, 'passage-sm3-5', null, null, 'The passage is mainly about', '[{"id":"a","text":"how to build strong houses with traditional mud brick"},{"id":"b","text":"the life and rule of Imam Muhammad bin Saud"},{"id":"c","text":"tourism and shopping in modern Riyadh today"},{"id":"d","text":"the history of Diriyah and the protection of its heritage"}]'::jsonb, 'd', 'The passage covers Diriyah''s role in history and the restoration of At-Turaif.', 'easy', array['reading-comprehension','main-idea','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
