insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-22', 'reading', null, 'passage-sm3-6', null, null, 'What happens when water vapour rises and the air becomes colder?', '[{"id":"a","text":"It turns into groundwater under the desert."},{"id":"b","text":"It is absorbed by plants through their roots."},{"id":"c","text":"It condenses into drops that form clouds."},{"id":"d","text":"It evaporates again and rises higher."}]'::jsonb, 'c', 'The vapour condenses into tiny drops that gather to form clouds.', 'medium', array['reading-comprehension','detail','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-23', 'reading', null, 'passage-sm3-6', null, null, 'In the passage, ''they'' in ''When the drops grow heavy, they fall'' refers to', '[{"id":"a","text":"the clouds"},{"id":"b","text":"the rivers"},{"id":"c","text":"the plants"},{"id":"d","text":"the drops"}]'::jsonb, 'd', 'The heavy drops fall as rain, snow or hail.', 'easy', array['reading-comprehension','pronoun-reference','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-24', 'reading', null, 'passage-sm3-6', null, null, 'Why is underground water so valuable in Saudi Arabia?', '[{"id":"a","text":"Rain is rare and the water is replaced very slowly."},{"id":"b","text":"It is much warmer than the rainwater on the surface."},{"id":"c","text":"It evaporates quickly when it reaches the surface."},{"id":"d","text":"It comes directly from the sea through the rocks."}]'::jsonb, 'a', 'The passage says rain is rare there and the groundwater takes thousands of years to be replaced.', 'hard', array['reading-comprehension','inference','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-25', 'reading', null, 'passage-sm3-7', null, null, 'In the passage, the word ''hatch'' is closest in meaning to', '[{"id":"a","text":"fall down from a tree"},{"id":"b","text":"dig a hole in sand"},{"id":"c","text":"come out of an egg"},{"id":"d","text":"swim away from shore"}]'::jsonb, 'c', 'The baby turtles hatch after about two months, meaning they emerge from their eggs.', 'easy', array['reading-comprehension','vocabulary','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-26', 'reading', null, 'passage-sm3-7', null, null, 'According to the passage, why do many baby turtles go inland?', '[{"id":"a","text":"They are looking for food."},{"id":"b","text":"They are following their mother."},{"id":"c","text":"The sea is too cold."},{"id":"d","text":"Artificial lights confuse them."}]'::jsonb, 'd', 'Hatchlings head toward the brightest horizon, and artificial lights on beaches mislead them.', 'easy', array['reading-comprehension','detail','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-27', 'reading', null, 'passage-sm3-7', null, null, 'In the passage, ''it'' in ''to reach it'' refers to', '[{"id":"a","text":"the beach"},{"id":"b","text":"the sea"},{"id":"c","text":"the nest"},{"id":"d","text":"the egg"}]'::jsonb, 'a', 'Females travel thousands of kilometres to reach the beach where they were born.', 'medium', array['reading-comprehension','pronoun-reference','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-28', 'reading', null, 'passage-sm3-7', null, null, 'What is the author''s attitude to the work of conservation groups?', '[{"id":"a","text":"Doubtful, because it costs too much money to continue"},{"id":"b","text":"Positive, because it shows that small changes can help"},{"id":"c","text":"Critical, because it harms tourism in the area"},{"id":"d","text":"Neutral, because it has no real effect on wildlife"}]'::jsonb, 'b', 'The last sentence says their work shows small changes in behaviour can save an ancient species.', 'medium', array['reading-comprehension','author-opinion','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-29', 'reading', null, 'passage-sm3-8', null, null, 'In the passage, the word ''convenience'' is closest in meaning to', '[{"id":"a","text":"high cost and risk"},{"id":"b","text":"bad quality goods"},{"id":"c","text":"long delay in delivery"},{"id":"d","text":"ease and comfort"}]'::jsonb, 'd', 'Shoppers can buy from home at any hour, which is easy and comfortable.', 'medium', array['reading-comprehension','vocabulary','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-30', 'reading', null, 'passage-sm3-8', null, null, 'All of the following are disadvantages of online shopping mentioned in the passage EXCEPT', '[{"id":"a","text":"higher prices than in shops"},{"id":"b","text":"not being able to try products"},{"id":"c","text":"packaging waste"},{"id":"d","text":"products that look different from the pictures"}]'::jsonb, 'a', 'Comparing prices is described as a benefit; higher prices are not mentioned as a drawback.', 'medium', array['reading-comprehension','detail','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-31', 'reading', null, 'passage-sm3-8', null, null, 'In the passage, ''they'' in ''if they are not satisfied'' refers to', '[{"id":"a","text":"items"},{"id":"b","text":"shoppers"},{"id":"c","text":"small businesses"},{"id":"d","text":"prices"}]'::jsonb, 'b', 'Shoppers can return items if they (the shoppers) are not satisfied.', 'medium', array['reading-comprehension','pronoun-reference','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-32', 'reading', null, 'passage-sm3-8', null, null, 'What does the author predict about the future?', '[{"id":"a","text":"Traditional shops will disappear completely within a few years."},{"id":"b","text":"Online shopping will stop growing in the near future."},{"id":"c","text":"The most successful companies will combine online and shop selling."},{"id":"d","text":"Small businesses will be forced to close their doors."}]'::jsonb, 'c', 'The last sentence says the most successful companies will probably combine both methods.', 'hard', array['reading-comprehension','author-opinion','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-33', 'reading', null, 'passage-sm3-9', null, null, 'In the passage, the word ''admitted'' is closest in meaning to', '[{"id":"a","text":"allowed to enter"},{"id":"b","text":"asked to leave early"},{"id":"c","text":"paid for in advance"},{"id":"d","text":"taught at home"}]'::jsonb, 'a', 'Women were not allowed to enter the university, so she went abroad.', 'medium', array['reading-comprehension','vocabulary','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-34', 'reading', null, 'passage-sm3-9', null, null, 'Why did Marie Curie move to Paris?', '[{"id":"a","text":"She wanted to marry Pierre Curie who lived in Paris."},{"id":"b","text":"Women were not admitted to her local university."},{"id":"c","text":"She was offered a job in a hospital in the city."},{"id":"d","text":"Her family had moved there a few years before."}]'::jsonb, 'b', 'She could not study at home because women were not admitted, so she saved money and moved to Paris.', 'easy', array['reading-comprehension','detail','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-35', 'reading', null, 'passage-sm3-9', null, null, 'In the passage, ''whose'' in ''radiation, whose dangers were not understood'' refers to', '[{"id":"a","text":"Marie Curie"},{"id":"b","text":"the First World War"},{"id":"c","text":"radiation"},{"id":"d","text":"the X-ray units"}]'::jsonb, 'c', 'The dangers of radiation were not understood at the time.', 'medium', array['reading-comprehension','pronoun-reference','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-36', 'reading', null, 'passage-sm3-9', null, null, 'What can be inferred about Marie Curie?', '[{"id":"a","text":"She disliked working with others."},{"id":"b","text":"She gave up science in 1911."},{"id":"c","text":"She was unknown during her lifetime."},{"id":"d","text":"She was determined and hardworking."}]'::jsonb, 'd', 'She saved money for years, worked long hours and won two Nobel Prizes.', 'medium', array['reading-comprehension','inference','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-37', 'reading', null, 'passage-sm3-10', null, null, 'In the passage, the word ''decades'' is closest in meaning to', '[{"id":"a","text":"periods of one hundred years"},{"id":"b","text":"periods of ten years"},{"id":"c","text":"single days"},{"id":"d","text":"short seasons"}]'::jsonb, 'b', 'A decade is ten years; the passage says rubbish can take decades or centuries to break down.', 'easy', array['reading-comprehension','vocabulary','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-38', 'reading', null, 'passage-sm3-10', null, null, 'Why is aluminium especially valuable for recycling?', '[{"id":"a","text":"It is much lighter than paper and easy to carry."},{"id":"b","text":"It breaks down quickly in landfills and disappears."},{"id":"c","text":"It can be reused again and again without losing quality."},{"id":"d","text":"It can be mixed with any plastic without problems."}]'::jsonb, 'c', 'Metals such as aluminium can be melted and reused repeatedly without losing quality.', 'medium', array['reading-comprehension','detail','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-39', 'reading', null, 'passage-sm3-10', null, null, 'In the passage, ''it'' in ''much of it ends up in landfills'' refers to', '[{"id":"a","text":"the year"},{"id":"b","text":"paper"},{"id":"c","text":"the environment"},{"id":"d","text":"rubbish"}]'::jsonb, 'd', 'People throw away rubbish, and much of it (the rubbish) ends up in landfills.', 'easy', array['reading-comprehension','pronoun-reference','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-reading-40', 'reading', null, 'passage-sm3-10', null, null, 'What does the author believe about recycling?', '[{"id":"a","text":"It helps, but reducing and reusing are also needed."},{"id":"b","text":"It solves the whole problem of waste completely."},{"id":"c","text":"It is not worth doing because it costs too much."},{"id":"d","text":"It should replace all shops that sell new goods."}]'::jsonb, 'a', 'The author says recycling alone is not enough; we must also reduce and reuse.', 'hard', array['reading-comprehension','author-opinion','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
