insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-grammar-3', 'grammar', null, null, null, null, 'How ___ water do you drink every day?', '[{"id":"a","text":"many"},{"id":"b","text":"few"},{"id":"c","text":"much"},{"id":"d","text":"a few"}]'::jsonb, 'c', '''Water'' is uncountable, so we ask ''How much''.', 'easy', array['countable-uncountable','quantifiers','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-grammar-4', 'grammar', null, null, null, null, 'I have ___ free time today, so I can''t join you.', '[{"id":"a","text":"a little"},{"id":"b","text":"few"},{"id":"c","text":"a few"},{"id":"d","text":"little"}]'::jsonb, 'd', '''Little'' (without ''a'') means almost none and fits an uncountable noun with a negative result.', 'medium', array['countable-uncountable','quantifiers','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
