insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-grammar-22', 'grammar', null, null, null, null, 'If we had left earlier, we ___ the traffic.', '[{"id":"a","text":"would avoid"},{"id":"b","text":"will avoid"},{"id":"c","text":"would have avoided"},{"id":"d","text":"had avoided"}]'::jsonb, 'c', 'Third conditional: if + past perfect, would have + past participle.', 'hard', array['conditionals','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
