insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-grammar-24', 'grammar', null, null, null, null, 'I wish I ___ to the party last night.', '[{"id":"a","text":"had gone"},{"id":"b","text":"went"},{"id":"c","text":"would go"},{"id":"d","text":"go"}]'::jsonb, 'a', 'A regret about the past takes the past perfect after ''wish''.', 'hard', array['wish','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-grammar-25', 'grammar', null, null, null, null, 'He ___ smoke, but he gave up last year.', '[{"id":"a","text":"is used to"},{"id":"b","text":"uses to"},{"id":"c","text":"used to"},{"id":"d","text":"was used to"}]'::jsonb, 'c', '''Used to'' + base verb describes a past habit that has ended.', 'medium', array['used-to','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
