insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-grammar-27', 'grammar', null, null, null, null, 'I am late, ___?', '[{"id":"a","text":"aren''t I"},{"id":"b","text":"am not I"},{"id":"c","text":"amn''t I"},{"id":"d","text":"don''t I"}]'::jsonb, 'a', 'The standard tag for ''I am'' is ''aren''t I?''.', 'hard', array['question-tags','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
