insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-grammar-30', 'grammar', null, null, null, null, 'Hardly ___ the house when it started to rain.', '[{"id":"a","text":"had we left"},{"id":"b","text":"we had left"},{"id":"c","text":"did we leave"},{"id":"d","text":"we left"}]'::jsonb, 'a', 'After ''Hardly'' at the start, the auxiliary comes before the subject: had we left.', 'hard', array['inversion','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-listening-1', 'listening', null, null, '/audio/listening/sm3-listening-1.mp3', 'Customer: Excuse me, I''m looking for a book called The Desert Stars.
Assistant: Let me check the computer... I''m sorry, we sold the last copy yesterday, but we can order it for you. It would arrive in about five days.
Customer: That''s a bit long. Is there an electronic version?
Assistant: Yes, the e-book costs twenty-eight riyals, while the printed book costs forty-five.
Customer: Then I''ll buy the printed one, because I want to give it to my cousin as a birthday present. Her birthday is in ten days, so five days is fine.
