insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-listening-7', 'listening', null, null, '/audio/listening/sm3-listening-7.mp3', 'Student: Good morning. I''d like to talk about changing my major from biology to computer science.
Advisor: That''s a big decision. Why do you want to change?
Student: I enjoy programming much more, and I''ve already taken two introductory courses online.
Advisor: I see. The problem is that the change must be requested before the end of this month, and you''ll need a minimum grade of B in the introductory programming course here.
Student: I got a B-plus last semester.
Advisor: Then you qualify. Please fill in this form and bring it back with your transcript on Wednesday.', 'What does the student want to do?', '[{"id":"a","text":"Leave the university"},{"id":"b","text":"Take an online course only"},{"id":"c","text":"Move to a different university"},{"id":"d","text":"Change his major to computer science"}]'::jsonb, 'd', 'He wants to change his major from biology to computer science.', 'easy', array['listening-comprehension','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
