insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-listening-9', 'listening', null, null, '/audio/listening/sm3-listening-9.mp3', 'Receptionist: Good afternoon, Palm Hotel.
Caller: Hello. I''d like to book a double room for three nights, starting on the twelfth of March.
Receptionist: I''m sorry, the double rooms are full on the twelfth. We have a twin room available, or we could offer a double from the thirteenth.
Caller: I''ll take the twin room for the first night and then change to a double. Is breakfast included?
Receptionist: Yes, breakfast is included, but parking costs fifteen riyals a day.
Caller: That''s fine.', 'Why can''t the caller have a double room on the twelfth?', '[{"id":"a","text":"The hotel is closed."},{"id":"b","text":"The price is too high."},{"id":"c","text":"All the double rooms are full."},{"id":"d","text":"He asked for too many nights."}]'::jsonb, 'c', 'The receptionist says the double rooms are full on the twelfth.', 'easy', array['listening-comprehension','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
