insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-listening-11', 'listening', null, null, '/audio/listening/sm3-listening-11.mp3', 'Presenter: And now the weather. Tomorrow morning will start sunny across the central region, with temperatures around twenty-two degrees. By the afternoon, clouds will gather in the west, and there is a strong chance of heavy rain in the mountains from four o''clock. Drivers are advised to avoid the valley roads in the evening because of the risk of floods. On Friday, the weather will become dry and warm again.', 'When is rain expected in the mountains?', '[{"id":"a","text":"From four o''clock in the afternoon"},{"id":"b","text":"In the early morning, before sunrise"},{"id":"c","text":"Late on Saturday night"},{"id":"d","text":"At midnight, when it turns colder"}]'::jsonb, 'a', 'Heavy rain is likely in the mountains from four o''clock.', 'medium', array['listening-comprehension','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
