insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm3-listening-13', 'listening', null, null, '/audio/listening/sm3-listening-13.mp3', 'Member: Hi, I''d like some information about memberships.
Staff: Sure. We have a monthly plan for two hundred riyals, or an annual plan for eighteen hundred.
Member: That''s quite a difference. How much would I save on the annual plan?
Staff: Twelve months at two hundred would be twenty-four hundred, so you save six hundred riyals.
Member: I''m only sure about staying for six months.
Staff: Then the monthly plan is safer. If you pay month by month, you can stop at any time.
Member: OK, I''ll start with that and decide later.', 'How much would the member save with the annual plan?', '[{"id":"a","text":"200 riyals"},{"id":"b","text":"1,800 riyals"},{"id":"c","text":"2,400 riyals"},{"id":"d","text":"600 riyals"}]'::jsonb, 'd', 'Twelve months at 200 riyals is 2,400, so the annual plan at 1,800 saves 600.', 'medium', array['listening-comprehension','step-mock-3']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
