insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-17', 'reading', null, 'passage-sm4-5', null, null, 'In the passage, the word ''labourers'' is closest in meaning to', '[{"id":"a","text":"workers who do physical jobs"},{"id":"b","text":"rulers of a large country"},{"id":"c","text":"priests who served the pharaoh"},{"id":"d","text":"visitors who came from abroad"}]'::jsonb, 'a', 'The builders were paid workers who did the heavy physical work.', 'medium', array['reading-comprehension','vocabulary','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-18', 'reading', null, 'passage-sm4-5', null, null, 'How did the workers probably move the heavy blocks?', '[{"id":"a","text":"With strong horses and ropes"},{"id":"b","text":"On wooden sledges over wet sand"},{"id":"c","text":"On boats down the river Nile"},{"id":"d","text":"With metal wheels and carts"}]'::jsonb, 'b', 'They probably used wooden sledges and poured water on the sand to ease the dragging.', 'medium', array['reading-comprehension','detail','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-19', 'reading', null, 'passage-sm4-5', null, null, 'In the passage, ''this outer layer'' refers to', '[{"id":"a","text":"the sand in front of the sledges"},{"id":"b","text":"the workers'' villages nearby"},{"id":"c","text":"the white limestone covering"},{"id":"d","text":"the heavy stone blocks inside"}]'::jsonb, 'c', 'The pyramid was covered with smooth white limestone; most of this outer layer has gone.', 'medium', array['reading-comprehension','pronoun-reference','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
