insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-22', 'reading', null, 'passage-sm4-6', null, null, 'Why is molten glass poured onto melted tin?', '[{"id":"a","text":"So that it cools more slowly and safely."},{"id":"b","text":"So that it changes colour as it spreads."},{"id":"c","text":"So that it spreads out into flat sheets."},{"id":"d","text":"So that it can be recycled again later."}]'::jsonb, 'c', 'On the tin bath the glass spreads out evenly and forms perfectly flat sheets.', 'medium', array['reading-comprehension','detail','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
