insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-26', 'reading', null, 'passage-sm4-7', null, null, 'How do emperor penguins avoid suffering the cold for long?', '[{"id":"a","text":"They dig holes in the ice."},{"id":"b","text":"They swim to warmer seas."},{"id":"c","text":"They sleep for most of the winter."},{"id":"d","text":"They take turns at the windy outer edge."}]'::jsonb, 'd', 'Birds move from the edge to the centre and back, so none stays at the edge for long.', 'medium', array['reading-comprehension','detail','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
