insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-29', 'reading', null, 'passage-sm4-8', null, null, 'In the passage, the word ''constantly'' is closest in meaning to', '[{"id":"a","text":"rarely"},{"id":"b","text":"suddenly"},{"id":"c","text":"by accident"},{"id":"d","text":"all the time"}]'::jsonb, 'd', 'Teenagers who check their phones constantly check them again and again.', 'easy', array['reading-comprehension','vocabulary','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-30', 'reading', null, 'passage-sm4-8', null, null, 'According to the writer, why may teenagers feel their own lives are boring?', '[{"id":"a","text":"They see only the best moments of other people''s lives."},{"id":"b","text":"They have too much homework to do every night."},{"id":"c","text":"They are not allowed to use phones at school."},{"id":"d","text":"They never see their relatives who live abroad."}]'::jsonb, 'a', 'The writer says comparison with other people''s best moments can make their own lives seem boring.', 'medium', array['reading-comprehension','detail','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-31', 'reading', null, 'passage-sm4-8', null, null, 'In the passage, ''those'' in ''those who check their phones constantly'' refers to', '[{"id":"a","text":"relatives"},{"id":"b","text":"teenagers"},{"id":"c","text":"studies"},{"id":"d","text":"parents"}]'::jsonb, 'b', 'The sentence is about young people who check their phones all the time.', 'medium', array['reading-comprehension','pronoun-reference','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-32', 'reading', null, 'passage-sm4-8', null, null, 'What is the writer''s position on social media?', '[{"id":"a","text":"It should be banned for all teenagers."},{"id":"b","text":"It has no benefits at all for young people."},{"id":"c","text":"It should be used with sensible limits."},{"id":"d","text":"It is always better than reading books."}]'::jsonb, 'c', 'The writer rejects a ban and suggests simple family rules instead.', 'medium', array['reading-comprehension','author-opinion','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-33', 'reading', null, 'passage-sm4-9', null, null, 'In the passage, the word ''untidy'' is closest in meaning to', '[{"id":"a","text":"not neat"},{"id":"b","text":"very large"},{"id":"c","text":"brand new"},{"id":"d","text":"well known"}]'::jsonb, 'a', 'Fleming forgot to clean a dish, which suggests his laboratory was not neat.', 'easy', array['reading-comprehension','vocabulary','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-34', 'reading', null, 'passage-sm4-9', null, null, 'What did Fleming notice in the dish?', '[{"id":"a","text":"The mould had turned blue and then died."},{"id":"b","text":"The bacteria had died around the mould."},{"id":"c","text":"The bacteria had grown much larger in size."},{"id":"d","text":"The dish had been broken in the laboratory."}]'::jsonb, 'b', 'Around the mould the bacteria had died.', 'easy', array['reading-comprehension','detail','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-35', 'reading', null, 'passage-sm4-9', null, null, 'In the passage, ''it'' in ''he named it penicillin'' refers to', '[{"id":"a","text":"the untidy laboratory in London"},{"id":"b","text":"the dish that he had forgotten"},{"id":"c","text":"the substance made by the mould"},{"id":"d","text":"the holiday that he had just taken"}]'::jsonb, 'c', 'He realised the mould produced a substance that kills germs and named that substance penicillin.', 'medium', array['reading-comprehension','pronoun-reference','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-36', 'reading', null, 'passage-sm4-9', null, null, 'Why was penicillin not used to treat patients at once?', '[{"id":"a","text":"Doctors refused to try it."},{"id":"b","text":"It harmed the patients."},{"id":"c","text":"It was too expensive to buy."},{"id":"d","text":"Fleming could not make enough of it."}]'::jsonb, 'd', 'The passage says he was unable to produce enough of the substance.', 'hard', array['reading-comprehension','inference','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-37', 'reading', null, 'passage-sm4-10', null, null, 'In the passage, the word ''permanent'' is closest in meaning to', '[{"id":"a","text":"very large and wide"},{"id":"b","text":"lasting all the time"},{"id":"c","text":"fast-flowing and strong"},{"id":"d","text":"happening only sometimes"}]'::jsonb, 'b', 'A permanent river flows all year round, and Saudi Arabia has none.', 'medium', array['reading-comprehension','vocabulary','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-38', 'reading', null, 'passage-sm4-10', null, null, 'What happens in a reverse osmosis plant?', '[{"id":"a","text":"Seawater is heated until it turns into vapour."},{"id":"b","text":"Salt is burned off in a very hot furnace."},{"id":"c","text":"Pumps push seawater through filters that block the salt."},{"id":"d","text":"Fresh water is mixed with salt to clean it."}]'::jsonb, 'c', 'Powerful pumps push seawater through very fine filters that block the salt.', 'medium', array['reading-comprehension','detail','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-reading-39', 'reading', null, 'passage-sm4-10', null, null, 'In the passage, ''it'' in ''so it relies heavily on desalination'' refers to', '[{"id":"a","text":"rainfall"},{"id":"b","text":"desalination"},{"id":"c","text":"seawater"},{"id":"d","text":"Saudi Arabia"}]'::jsonb, 'd', 'Saudi Arabia has little rain, so it (the kingdom) relies on desalination.', 'easy', array['reading-comprehension','pronoun-reference','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
