insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-grammar-24', 'grammar', null, null, null, null, 'She wishes she ___ the exam more seriously last year.', '[{"id":"a","text":"had taken"},{"id":"b","text":"took"},{"id":"c","text":"would take"},{"id":"d","text":"takes"}]'::jsonb, 'a', 'A regret about the past takes the past perfect after ''wish''.', 'hard', array['wish','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
