insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-grammar-30', 'grammar', null, null, null, null, 'Only after the exam ___ how difficult it was.', '[{"id":"a","text":"did I realise"},{"id":"b","text":"I realised"},{"id":"c","text":"I did realise"},{"id":"d","text":"realised I"}]'::jsonb, 'a', 'After ''Only after...'' at the start, the auxiliary comes before the subject: did I realise.', 'hard', array['inversion','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-listening-1', 'listening', null, null, '/audio/listening/sm4-listening-1.mp3', 'Student: Hi, I''d like to join the photography club.
Organiser: Great! We meet every Wednesday at five in Room 204, and the membership fee is sixty riyals for the whole year.
Student: Do I need my own camera?
Organiser: Not at the beginning. The club has six cameras that members can borrow, but you must return them the same day.
Student: And when is the first trip?
Organiser: We''re planning a visit to the old town next month, on the second Saturday.
Student: Perfect. Where do I pay?
Organiser: At the student services office, and bring the receipt to the next meeting.', 'When does the club meet?', '[{"id":"a","text":"Every Wednesday at five"},{"id":"b","text":"Every Saturday at five"},{"id":"c","text":"Every Tuesday at six"},{"id":"d","text":"Once a month"}]'::jsonb, 'a', 'The organiser says they meet every Wednesday at five in Room 204.', 'easy', array['listening-comprehension','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
