insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-listening-7', 'listening', null, null, '/audio/listening/sm4-listening-7.mp3', 'Clerk: Welcome to National Bank. How can I help?
