insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-listening-9', 'listening', null, null, '/audio/listening/sm4-listening-9.mp3', 'Agent: Desert Tours, good morning.
Caller: Hi, I booked the Friday morning tour to the red dunes, but I''d like to change it.
Agent: What day suits you?
Caller: Saturday, if possible, because my cousins are arriving on Friday night.
Agent: The Saturday tour is full in the morning, but there''s one at three in the afternoon.
Caller: In the afternoon is better, actually, because it''s cooler.
Agent: Great, I''ve moved your booking. The price stays the same, one hundred and fifty riyals per person.', 'Why does the caller want to change the day?', '[{"id":"a","text":"The tour is too expensive for his family."},{"id":"b","text":"He is ill and cannot travel."},{"id":"c","text":"His cousins are arriving on Friday night."},{"id":"d","text":"The dunes are closed on that day."}]'::jsonb, 'c', 'He says his cousins arrive on Friday night.', 'easy', array['listening-comprehension','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
