insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-listening-11', 'listening', null, null, '/audio/listening/sm4-listening-11.mp3', 'Announcement: May I have your attention please. The ten-fifteen bus to Abha has been cancelled because of a mechanical problem. Passengers holding tickets for this bus can use the eleven o''clock service from the same bay, or ask for a full refund at the ticket office. Please remember that the eleven o''clock bus is already half full, so we recommend choosing your seat quickly.', 'Why was the bus cancelled?', '[{"id":"a","text":"There was a mechanical problem."},{"id":"b","text":"The weather was bad."},{"id":"c","text":"The driver was ill."},{"id":"d","text":"There were too few passengers."}]'::jsonb, 'a', 'The announcement gives a mechanical problem as the reason.', 'easy', array['listening-comprehension','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
