insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-listening-13', 'listening', null, null, '/audio/listening/sm4-listening-13.mp3', 'Doctor: Come in. What seems to be the problem?
Patient: I''ve had a sore throat and a cough for three days, and last night I had a fever.
Doctor: Let me check... Your throat is red, but your chest sounds clear. I think it''s a virus, so antibiotics won''t help. Drink plenty of water, rest, and take these tablets twice a day after meals.
Patient: Should I go to work tomorrow?
Doctor: I''d stay at home for two days. If the fever returns, come back immediately.', 'What does the doctor think is wrong?', '[{"id":"a","text":"A chest infection"},{"id":"b","text":"An allergy"},{"id":"c","text":"A broken tooth"},{"id":"d","text":"A viral infection"}]'::jsonb, 'd', 'He says it is a virus and that the chest sounds clear.', 'easy', array['listening-comprehension','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
