insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-listening-18', 'listening', null, null, '/audio/listening/sm4-listening-18.mp3', 'Nada: So we''re meeting at the library on Monday to revise for the chemistry test?
Salma: Actually, Monday won''t work, because the library closes early for maintenance. How about Tuesday at four?
Nada: Tuesday is perfect for me. Should we study the whole book?
Salma: No, the teacher said the test covers only chapters five to eight.
