insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-writing-3', 'writingAnalysis', null, null, null, null, 'Which sentence uses capital letters correctly?', '[{"id":"a","text":"We studied arabic, english and History last term."},{"id":"b","text":"We studied Arabic, English and History last Term."},{"id":"c","text":"We studied Arabic, English and history last term."},{"id":"d","text":"we studied Arabic, English and history last term."}]'::jsonb, 'c', 'Language names are capitalised, while school subjects like history and the word term are not.', 'easy', array['capitalization','proper-nouns','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
