insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm4-writing-9', 'writingAnalysis', null, null, null, null, 'Choose the sentence that means the same as: "He is too tired to drive."', '[{"id":"a","text":"He is tired, so he drives fast."},{"id":"b","text":"He is not tired, so he can drive."},{"id":"c","text":"He is so tired that he cannot drive."},{"id":"d","text":"He drives because he is tired."}]'::jsonb, 'c', '''Too tired to drive'' means so tired that he cannot drive.', 'easy', array['sentence-meaning','step-mock-4']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
