insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-18', 'reading', null, 'passage-sm5-5', null, null, 'Why do most climbers carry bottled oxygen?', '[{"id":"a","text":"The mountain has no air at all once climbers pass the first camp."},{"id":"b","text":"The air at that height has only about a third of the oxygen at sea level."},{"id":"c","text":"Bottled oxygen helps the climbers to keep warm in the wind."},{"id":"d","text":"Climbing laws in Nepal and Tibet require every climber to carry it."}]'::jsonb, 'b', 'The thin air contains only about a third of the oxygen found at sea level.', 'medium', array['reading-comprehension','detail','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
