insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-20', 'reading', null, 'passage-sm5-5', null, null, 'What does the writer suggest about Sherpa guides?', '[{"id":"a","text":"They are not used to the altitude of the mountain."},{"id":"b","text":"They climb only for money and for no other reason."},{"id":"c","text":"They cause most of the waste that is left on the slopes."},{"id":"d","text":"Their dangerous work deserves more recognition."}]'::jsonb, 'd', 'Their work is described as dangerous and often unrecognised.', 'hard', array['reading-comprehension','author-opinion','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
