insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-23', 'reading', null, 'passage-sm5-6', null, null, 'In the passage, ''this attention'' in the last sentence refers to', '[{"id":"a","text":"the fires that damaged the district"},{"id":"b","text":"the merchants who came from India"},{"id":"c","text":"the sea breezes that cool the houses"},{"id":"d","text":"the UNESCO listing and restoration work"}]'::jsonb, 'd', 'The listing in 2014 and the restoration programme are the attention the area has received.', 'hard', array['reading-comprehension','pronoun-reference','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
