insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-30', 'reading', null, 'passage-sm5-8', null, null, 'What environmental problem do washed synthetic fabrics cause?', '[{"id":"a","text":"Tiny plastic fibres end up in rivers and oceans."},{"id":"b","text":"They use thousands of litres of water every time they are worn."},{"id":"c","text":"They produce smoke when they are made in factories."},{"id":"d","text":"They make rivers warmer when they are thrown away."}]'::jsonb, 'a', 'Many synthetic fabrics release tiny plastic fibres when washed, which reach rivers and oceans.', 'medium', array['reading-comprehension','detail','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-31', 'reading', null, 'passage-sm5-8', null, null, 'In the passage, ''they'' in ''more power than they realise'' refers to', '[{"id":"a","text":"companies"},{"id":"b","text":"shoppers"},{"id":"c","text":"clothes"},{"id":"d","text":"rivers"}]'::jsonb, 'b', '''I think shoppers have more power than they realise.''', 'medium', array['reading-comprehension','pronoun-reference','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-32', 'reading', null, 'passage-sm5-8', null, null, 'What is the writer''s main message?', '[{"id":"a","text":"Clothes should never be washed because they release plastic."},{"id":"b","text":"Companies should stop making any new clothes at all."},{"id":"c","text":"Shoppers can reduce the harm by buying less and choosing quality."},{"id":"d","text":"Fashion is a waste of time and money for everybody."}]'::jsonb, 'c', 'The writer asks shoppers to buy fewer items, choose quality and repair clothes.', 'medium', array['reading-comprehension','author-opinion','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-33', 'reading', null, 'passage-sm5-9', null, null, 'In the passage, the word ''dictate'' is closest in meaning to', '[{"id":"a","text":"say aloud for someone to write down"},{"id":"b","text":"read a text silently to oneself"},{"id":"c","text":"draw a map of a journey for others"},{"id":"d","text":"copy a text word for word from a book"}]'::jsonb, 'a', 'He told the story of his travels so that a scribe could record it.', 'medium', array['reading-comprehension','vocabulary','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-34', 'reading', null, 'passage-sm5-9', null, null, 'Why did he often work as a judge?', '[{"id":"a","text":"Because rulers feared him"},{"id":"b","text":"Because of his religious education"},{"id":"c","text":"Because he needed a boat"},{"id":"d","text":"Because he was born in India"}]'::jsonb, 'b', 'The passage says he worked as a judge because of his religious education.', 'easy', array['reading-comprehension','detail','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-35', 'reading', null, 'passage-sm5-9', null, null, 'In the passage, ''This book'' refers to', '[{"id":"a","text":"the Hajj"},{"id":"b","text":"the caravan"},{"id":"c","text":"the Rihla"},{"id":"d","text":"the ruler''s order"}]'::jsonb, 'c', 'The ruler asked him to dictate an account; the resulting book is the Rihla.', 'easy', array['reading-comprehension','pronoun-reference','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-36', 'reading', null, 'passage-sm5-9', null, null, 'Why is the Rihla valuable to historians?', '[{"id":"a","text":"It is the shortest and simplest travel book ever written."},{"id":"b","text":"It was written by a ruler of Morocco himself."},{"id":"c","text":"It lists the prices of goods in every market."},{"id":"d","text":"It describes cities and customs few others recorded."}]'::jsonb, 'd', 'The passage says it describes places and customs rarely recorded by other writers.', 'medium', array['reading-comprehension','inference','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
