insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-38', 'reading', null, 'passage-sm5-10', null, null, 'How can AI help doctors?', '[{"id":"a","text":"By replacing all of the nurses and staff in hospitals"},{"id":"b","text":"By cooking and serving meals to the patients"},{"id":"c","text":"By examining many X-ray images to help spot early signs of disease"},{"id":"d","text":"By writing prescriptions for patients without a doctor"}]'::jsonb, 'c', 'AI programs can examine thousands of X-ray images and help doctors spot early signs of disease.', 'medium', array['reading-comprehension','detail','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-39', 'reading', null, 'passage-sm5-10', null, null, 'In the passage, ''they'' in ''they may be unfair'' refers to', '[{"id":"a","text":"doctors"},{"id":"b","text":"students"},{"id":"c","text":"patterns"},{"id":"d","text":"AI systems"}]'::jsonb, 'd', '''Systems can make mistakes, and they may be unfair if the data...''', 'medium', array['reading-comprehension','pronoun-reference','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-reading-40', 'reading', null, 'passage-sm5-10', null, null, 'What do the experts in the passage advise about AI?', '[{"id":"a","text":"Treat it as a helpful assistant and check important results."},{"id":"b","text":"Avoid using it completely because it makes many mistakes"},{"id":"c","text":"Trust every result because the systems never fail"},{"id":"d","text":"Use it only in schools and never in other places"}]'::jsonb, 'a', 'They argue that people should treat AI as a helpful assistant and check important results themselves.', 'hard', array['reading-comprehension','author-opinion','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
