insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-grammar-4', 'grammar', null, null, null, null, 'She spends ___ time on her phone, so she never finishes her homework.', '[{"id":"a","text":"too many"},{"id":"b","text":"a few"},{"id":"c","text":"very few"},{"id":"d","text":"too much"}]'::jsonb, 'd', '''Time'' is uncountable, so ''too much'' is used.', 'medium', array['countable-uncountable','quantifiers','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
