insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-grammar-25', 'grammar', null, null, null, null, 'Did you ___ live in Jeddah?', '[{"id":"a","text":"used to"},{"id":"b","text":"using to"},{"id":"c","text":"use to"},{"id":"d","text":"be used to"}]'::jsonb, 'c', 'In questions with ''did'', the form is ''use to'' (without d).', 'medium', array['used-to','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
