insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-listening-1', 'listening', null, null, '/audio/listening/sm5-listening-1.mp3', 'Agent: Good morning, Sunrise Properties.
Caller: Hello, I saw your advert for the two-bedroom flat near the university.
Agent: Yes, it''s still available. The rent is three thousand riyals a month, including water but not electricity.
Caller: And is it furnished?
Agent: Partly. The kitchen has a fridge and a cooker, but the bedrooms are empty.
Caller: Can I see it this week?
Agent: The owner is free on Thursday after two o''clock, or on Saturday morning.
Caller: Thursday works. I''ll bring my father with me.', 'What is included in the rent?', '[{"id":"a","text":"Water"},{"id":"b","text":"Electricity"},{"id":"c","text":"Furniture"},{"id":"d","text":"Parking"}]'::jsonb, 'a', 'The rent includes water but not electricity.', 'easy', array['listening-comprehension','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-listening-2', 'listening', null, null, '/audio/listening/sm5-listening-1.mp3', 'Agent: Good morning, Sunrise Properties.
Caller: Hello, I saw your advert for the two-bedroom flat near the university.
Agent: Yes, it''s still available. The rent is three thousand riyals a month, including water but not electricity.
Caller: And is it furnished?
Agent: Partly. The kitchen has a fridge and a cooker, but the bedrooms are empty.
Caller: Can I see it this week?
Agent: The owner is free on Thursday after two o''clock, or on Saturday morning.
