insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-listening-9', 'listening', null, null, '/audio/listening/sm5-listening-9.mp3', 'Principal: Good morning, students. The class trip to the science museum will take place on Wednesday the fifth. The buses will leave the school at eight, not eight-thirty as announced earlier, because the museum opens at nine-thirty and the journey takes one hour. Please bring a packed lunch, since the museum café is closed for repairs. Parents must sign the permission form by Monday, and students without a form cannot join the trip.', 'What time will the buses leave?', '[{"id":"a","text":"At eight-thirty"},{"id":"b","text":"At nine"},{"id":"c","text":"At eight"},{"id":"d","text":"At nine-thirty"}]'::jsonb, 'c', 'The buses leave at eight, not eight-thirty as announced earlier.', 'medium', array['listening-comprehension','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
