insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-listening-11', 'listening', null, null, '/audio/listening/sm5-listening-11.mp3', 'Host: Good evening, Olive Garden restaurant.
Caller: Hello, I''d like to book a table for six on Friday evening.
Host: What time would you like?
Caller: Around eight o''clock.
Host: I''m sorry, we''re fully booked at eight, but we have a table at seven or at nine.
Caller: Seven is too early for my guests. Nine, then.
Host: Certainly. May I have a name?
Caller: Al-Harbi. And please, we need one high chair for a baby.
Host: No problem.', 'Why can''t the caller have a table at eight?', '[{"id":"a","text":"The restaurant is fully booked."},{"id":"b","text":"The restaurant is closed."},{"id":"c","text":"There is no table for six."},{"id":"d","text":"It is too noisy."}]'::jsonb, 'a', 'The host says they are fully booked at eight.', 'easy', array['listening-comprehension','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
