insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-listening-13', 'listening', null, null, '/audio/listening/sm5-listening-13.mp3', 'Tutor: Your essay is well organised, Omar, but you have a problem with tenses.
Omar: Which part?
Tutor: In the second paragraph you describe last summer, yet you switch to the present tense.
Omar: Oh, I see. Should I rewrite the whole essay?
Tutor: No, just correct the verbs and add a conclusion.
Omar: How many words should the conclusion be?
Tutor: About fifty. Bring it back on Sunday and we''ll check it together.', 'What is the main problem in Omar''s essay?', '[{"id":"a","text":"Poor organisation"},{"id":"b","text":"Spelling mistakes"},{"id":"c","text":"It is too short"},{"id":"d","text":"Mixed verb tenses"}]'::jsonb, 'd', 'He describes last summer but switches to the present tense.', 'easy', array['listening-comprehension','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
