insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-writing-2', 'writingAnalysis', null, null, null, null, 'Which sentence is punctuated correctly?', '[{"id":"a","text":"My sister who lives in Dammam, is a nurse."},{"id":"b","text":"My sister, who lives in Dammam, is a nurse."},{"id":"c","text":"My sister, who lives in Dammam is a nurse."},{"id":"d","text":"My sister who, lives in Dammam, is a nurse."}]'::jsonb, 'b', 'A non-essential clause is set off by a pair of commas.', 'medium', array['punctuation','commas','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-writing-3', 'writingAnalysis', null, null, null, null, 'Which sentence uses capital letters correctly?', '[{"id":"a","text":"Next march, we will visit Turkey and Italy."},{"id":"b","text":"Next March, we will visit turkey and italy."},{"id":"c","text":"Next March, we will visit Turkey and Italy."},{"id":"d","text":"next March, we will visit Turkey and Italy."}]'::jsonb, 'c', 'Capitalise the first word, months and country names.', 'easy', array['capitalization','proper-nouns','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-writing-4', 'writingAnalysis', null, null, null, null, 'Identify the error: "She enjoys to read novels in the evening."', '[{"id":"a","text":"\"enjoys\" should be \"enjoy\""},{"id":"b","text":"\"novels\" should be \"novel\""},{"id":"c","text":"\"in\" should be \"at\""},{"id":"d","text":"\"to read\" should be \"reading\""}]'::jsonb, 'd', '''Enjoy'' is followed by a gerund.', 'medium', array['error-identification','gerunds-infinitives','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-writing-5', 'writingAnalysis', null, null, null, null, 'Identify the error: "He doesn''t know nothing about the plan."', '[{"id":"a","text":"\"doesn''t\" should be \"don''t\""},{"id":"b","text":"\"nothing\" should be \"anything\""},{"id":"c","text":"\"know\" should be \"knows\""},{"id":"d","text":"\"about\" should be \"of\""}]'::jsonb, 'b', 'A double negative is incorrect; use ''anything'' after a negative verb.', 'medium', array['error-identification','negatives','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-writing-6', 'writingAnalysis', null, null, null, null, 'Identify the error: "The students, as well as the teacher, is ready to leave."', '[{"id":"a","text":"\"as well as\" should be \"and also\""},{"id":"b","text":"\"ready\" should be \"readily\""},{"id":"c","text":"\"is\" should be \"are\""},{"id":"d","text":"\"leave\" should be \"leaving\""}]'::jsonb, 'c', 'The verb agrees with the main subject ''The students'', not with the added phrase.', 'hard', array['error-identification','subject-verb-agreement','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-writing-7', 'writingAnalysis', null, null, null, null, 'Identify the error: "I have been working here since three years."', '[{"id":"a","text":"\"have been\" should be \"am\""},{"id":"b","text":"\"working\" should be \"work\""},{"id":"c","text":"\"here\" should be \"there\""},{"id":"d","text":"\"since\" should be \"for\""}]'::jsonb, 'd', '''For'' is used with a length of time; ''since'' with a starting point.', 'medium', array['error-identification','prepositions','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-writing-8', 'writingAnalysis', null, null, null, null, 'Choose the correct word order:', '[{"id":"a","text":"I have never seen such a beautiful sunset."},{"id":"b","text":"I never have seen such a beautiful sunset."},{"id":"c","text":"I have seen never such a beautiful sunset."},{"id":"d","text":"Never I have seen such a beautiful sunset."}]'::jsonb, 'a', 'Adverbs like ''never'' go between the auxiliary and the main verb.', 'medium', array['word-order','sentence-structure','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
insert into public.questions (id, section, course_id, passage_id, audio_url, transcript, prompt, options, correct_option_id, explanation, difficulty, tags) values ('sm5-writing-9', 'writingAnalysis', null, null, null, null, 'Choose the sentence that means the same as: "She is the tallest girl in the class."', '[{"id":"a","text":"She is shorter than the other girls."},{"id":"b","text":"Every girl in the class is taller than her."},{"id":"c","text":"No other girl in the class is as tall as she is."},{"id":"d","text":"She is as short as the other girls."}]'::jsonb, 'c', 'The superlative means no other girl is taller.', 'easy', array['sentence-meaning','comparatives','step-mock-5']::text[]) on conflict (id) do update set section = excluded.section, course_id = excluded.course_id, passage_id = excluded.passage_id, audio_url = excluded.audio_url, transcript = excluded.transcript, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, difficulty = excluded.difficulty, tags = excluded.tags;
